          tries += 1;
          var api = resolveMvu();
          if (api) {
            clearInterval(timer);
            finish(api);
          } else if (tries >= 60) {
            clearInterval(timer);
            finish(null);
          }
        }, 500);
      });
    }

    // 官方读取路径：Mvu.getMvuData({ type: "message", message_id: "latest" })。
    function readLatest() {
      var api = resolveMvu();
      if (!api || typeof api.getMvuData !== "function") return false;
      try {
        var data = api.getMvuData(option());
        if (data && data.stat_data && typeof data.stat_data === "object") {
          mvuApi = api;
          currentStat = data.stat_data;
          try {
            window.__ehxCurrentStatData = currentStat;
            window.__ehxDiagMsg = "MVU 已同步：" + Object.keys(currentStat).join(" / ");
          } catch (e) {}
          return true;
        }
      } catch (e) {}
      return false;
    }

    function avatarUrl() {
      try {
        var host = window.parent;
        var context = host.SillyTavern && typeof host.SillyTavern.getContext === "function"
          ? host.SillyTavern.getContext()
          : null;
        var character = context && context.characters && context.characters[context.characterId];
        var file = character && character.avatar;
        if (!file || file === "none") return "";
        // 取原始卡图（约 1280×1920）而不是酒馆头像缩略图：后者只有 96×144，
        // 放进 260–320px 的头像框会被放大到发糊。裁剪交给 CSS 的 object-fit / object-position。
        return host.location.origin + "/characters/" + encodeURIComponent(file);
      } catch (e) {
        return "";
      }
    }

    function applyPortrait() {
      var img = $("ehx-portrait");
      if (!img) return;
      var legacyAvatar = currentStat && currentStat["外貌"] && currentStat["外貌"]["自定义头像"];
      var src = readCustomAvatar("main", "艾迪娜·晨曦") || safeAvatarSource(legacyAvatar) || avatarUrl();
      if (!src) {
        img.removeAttribute("src");
        img.removeAttribute("data-ready");
        return;
      }
      img.addEventListener("load", function () { img.setAttribute("data-ready", "1"); }, { once: true });
      img.addEventListener("error", function () { img.removeAttribute("src"); img.removeAttribute("data-ready"); }, { once: true });
      img.src = src;
      if (img.complete && img.naturalWidth > 0) img.setAttribute("data-ready", "1");
    }

    function meter(label, value, ratio, fillClass) {
      var box = el("div");
      var row = el("div", "ehx-row");
      row.appendChild(el("span", "ehx-k", label));
      row.appendChild(el("span", "ehx-v", value));
      var bar = el("div", "ehx-bar");
      var inner = el("i", fillClass || null);
      inner.style.width = ratio + "%";
      bar.appendChild(inner);
      box.appendChild(row);
      box.appendChild(bar);
      return box;
    }

    function tile(value, label) {
      var box = el("div", "ehx-tile");
      box.appendChild(el("b", null, value));
      box.appendChild(el("span", null, label));
      return box;
    }

    function chip(text) { return el("span", "ehx-chip", text); }

    function fillPills(node, values, emptyText) {
      clear(node);
      var list = (values || []).filter(Boolean);
      if (!list.length) {
        node.appendChild(el("span", "ehx-empty", emptyText || "暂无"));
        return;
      }
      list.forEach(function (value) { node.appendChild(chip(value)); });
    }

    function defaultEquipName(slot) {
      if (slot === "内衣") return "真空";
      return "无";
    }

    function defaultEquip(slot) {
      var name = defaultEquipName(slot);
      if (slot === "内衣") {
        return { 名称: name, 位阶: "普通", 效果: "", 描述: "没有内衣遮挡，裙摆每一次摩擦都直接落在最敏感的肌肤上；走动时会不自觉地放慢脚步。", 加成: { "敏感": 6, "羞耻": 8 }, 技能: [] };
      }
      if (slot === "主手") return { 名称: name, 位阶: "普通", 效果: "", 描述: "空着手，什么都没有拿。", 加成: {}, 技能: [] };
      if (slot === "副手") return { 名称: name, 位阶: "普通", 效果: "", 描述: "副手空着。", 加成: {}, 技能: [] };
      return { 名称: name, 位阶: "普通", 效果: "", 描述: "这个槽位目前没有穿戴任何东西。", 加成: {}, 技能: [] };
    }

    function equipFor(slot, name) {
      var current = currentStat && currentStat["装备"] && currentStat["装备"][slot];
      if (current && current["名称"] === name) {
        return {
          名称: name,
          位阶: rankLabel(current["位阶"]),
          效果: str(current["效果"], ""),
          描述: str(current["描述"], "尚未记录这件装备的描述。"),
          加成: bonusOf(current),
          技能: Array.isArray(current["技能"]) ? current["技能"] : [],
          双手: current["双手"] === true
        };
      }
      if (!name || name === defaultEquipName(slot)) return defaultEquip(slot);
      var data = EQUIP_DATA[name];
      return {
        名称: name,
        位阶: rankLabel(data && data.rank),
        效果: data ? data.effect : "",
        描述: data ? data.description : "尚未记录这件装备的描述。",
        加成: data && data.bonus ? data.bonus : {},
        技能: data && Array.isArray(data.skills) ? data.skills.slice() : [],
        双手: !!(data && data.twoHanded)
      };
    }

    function isDefaultEquipment(slot, item) {
      var name = str(item && item["名称"], "");
      return !name || name === "无" || name === defaultEquipName(slot);
    }

    function inventoryItemToEquip(raw, slot) {
      return {
        名称: str(raw["名称"], ""),
        位阶: rankLabel(raw["位阶"]),
        效果: str(raw["效果"], ""),
        描述: str(raw["描述"], "尚未记录这件装备的描述。"),
        加成: bonusOf(raw),
        技能: Array.isArray(raw["技能"]) ? raw["技能"].map(function (skill) { return str(skill); }).filter(Boolean) : [],
        双手: raw["双手"] === true
      };
    }

    function inventoryEquipmentEntries(slot) {
      var result = [];
      items().forEach(function (raw, index) {
        if (!raw || raw === ARRAY_META || typeof raw !== "object") return;
        if (normalizeItemCategory(raw["类别"]) !== "装备") return;
        if (str(raw["槽位"], "") !== slot) return;
        result.push({ index: index, item: inventoryItemToEquip(raw, slot), raw: raw });
      });
      return result;
    }

    function addEquipmentToInventory(stat, slot, item) {
      if (isDefaultEquipment(slot, item)) return;
      if (!Array.isArray(stat["物品栏"])) stat["物品栏"] = [];
      var list = stat["物品栏"];
      var name = str(item["名称"], "");
      var existing = list.find(function (entry) {
        return entry && entry !== ARRAY_META && str(entry["名称"], "") === name && normalizeItemCategory(entry["类别"]) === "装备";
      });
      if (existing) {
        existing["数量"] = Math.max(1, num(existing["数量"], 1)) + 1;
        return;
      }
      list.push({
        名称: name,
        类别: "装备",
        槽位: slot,
        数量: 1,
        位阶: rankLabel(item["位阶"]),
        效果: str(item["效果"], ""),
        描述: str(item["描述"], ""),
        加成: bonusOf(item),
        技能: Array.isArray(item["技能"]) ? item["技能"].map(function (skill) { return str(skill); }).filter(Boolean) : [],
        双手: item["双手"] === true
      });
    }

    function bonusOf(equip) {
      var bonus = equip && equip["加成"];
      return bonus && typeof bonus === "object" && !Array.isArray(bonus) ? bonus : {};
    }

    // 变量里存的是「基础值」，装备加成不改写变量，只在面板上叠加显示。
    // 这样换装、卸装、换回来都不会累计误差，模型也不必维护加减法。
    var gearBonusTotals = {};

    function equippedBonusTotals() {
      var totals = {};
      var equip = currentStat && currentStat["装备"];
      if (!equip || typeof equip !== "object") return totals;
      Object.keys(equip).forEach(function (slot) {
        var bonus = bonusOf(equip[slot]);
        Object.keys(bonus).forEach(function (key) {
          if (!BONUS_TARGET[key]) return;
          totals[key] = num(totals[key], 0) + num(bonus[key], 0);
        });
      });
      return totals;
    }

    function withBonus(key, baseValue) {
      return num(baseValue, 0) + num(gearBonusTotals[key], 0);
    }

    // 装备附带的技能同步进 /技能，用「装备：<槽位>」标注来源，卸下时只回收装备来源的技能。
    function syncEquipSkills(stat) {
      var changed = false;
      var equipped = stat["装备"] && typeof stat["装备"] === "object" ? stat["装备"] : {};
      var wanted = {};
      Object.keys(equipped).forEach(function (slot) {
        var list = equipped[slot] && equipped[slot]["技能"];
        if (!Array.isArray(list)) return;
        list.forEach(function (raw) {
          var name = str(raw);
          if (name && !wanted[name]) {
            wanted[name] = {
              slot: slot,
              equipment: str(equipped[slot] && equipped[slot]["名称"], "装备")
            };
          }
        });
      });
      var list = Array.isArray(stat["技能"]) ? stat["技能"] : (stat["技能"] = []);
      for (var i = list.length - 1; i >= 0; i -= 1) {
        var entry = list[i];
        if (!entry || entry === ARRAY_META || typeof entry !== "object") continue;
        if (str(entry["来源"]).indexOf(GRANT_PREFIX) !== 0) continue;
        if (!wanted[str(entry["名称"])]) {
          list.splice(i, 1);
          changed = true;
        }
      }
      Object.keys(wanted).forEach(function (name) {
        var existing = list.find(function (entry) {
          return entry !== ARRAY_META && str(entry && typeof entry === "object" ? entry["名称"] : entry) === name;
        });
        var fallback = SKILL_DATA[name] || {};
        var meta = wanted[name];
        if (existing && typeof existing === "object") {
          var nextRank = rankLabel(existing["位阶"] || fallback.rank);
          var nextEffect = str(existing["效果"], fallback.effect || "由「" + meta.equipment + "」提供");
          var nextDescription = str(existing["描述"], fallback.description || "");
          if (String(existing["位阶"] || "") !== nextRank || String(existing["效果"] || "") !== nextEffect || String(existing["描述"] || "") !== nextDescription) {
            existing["位阶"] = nextRank;
            existing["效果"] = nextEffect;
            existing["描述"] = nextDescription;
            changed = true;
          }
          return;
        }
        if (existing) return;
        list.push({
          名称: name,
          位阶: rankLabel(fallback.rank),
          效果: fallback.effect || "由「" + meta.equipment + "」提供",
          描述: fallback.description || "穿戴「" + meta.equipment + "」期间可用。",
          来源: GRANT_PREFIX + meta.slot
        });
        changed = true;
      });
      return changed;
    }

    function ensureEquippedSkills() {
      if (!currentStat || equipSkillSyncInFlight) return;
      if (!syncEquipSkills(currentStat)) return;
      equipSkillSyncInFlight = true;
      writeLatest(function (stat) {
        syncEquipSkills(stat);
      }, "装备技能已同步", null, null).finally(function () {
        equipSkillSyncInFlight = false;
      });
    }

    function equipmentOptions(slot) {
      var options = [equipFor(slot, defaultEquipName(slot))];
      var current = currentStat && currentStat["装备"] && currentStat["装备"][slot];
      var currentName = current && current["名称"] ? current["名称"] : defaultEquipName(slot);
      if (currentName && currentName !== defaultEquipName(slot)) options.push(equipFor(slot, currentName));
      inventoryEquipmentEntries(slot).forEach(function (entry) {
        var name = entry.item["名称"];
        if (options.some(function (option) { return option["名称"] === name; })) return;
        options.push(entry.item);
      });
      return options;
    }

    function items() {
      return Array.isArray(currentStat && currentStat["物品栏"])
        ? currentStat["物品栏"].filter(function (item) { return item !== ARRAY_META; })
        : [];
    }

    function normalizeItemCategory(value) {
      var category = str(value, "");
      return ["装备", "道具", "杂物"].indexOf(category) >= 0 ? category : "道具";
    }

    function itemView(index) {
      var raw = items()[index] || {};
      var name = str(raw["名称"], "未命名物品");
      var fallback = ITEM_DATA[name] || {};
      return {
        index: index,
        name: name,
        category: normalizeItemCategory(raw["类别"]),
        slot: str(raw["槽位"], ""),
        quantity: num(raw["数量"], 1),
        rank: rankLabel(raw["位阶"] || fallback.rank),
        effect: str(raw["效果"], fallback.effect || "未记录效果"),
        description: str(raw["描述"], fallback.description || "尚未记录物品描述。"),
        bonus: bonusOf(raw),
        skills: Array.isArray(raw["技能"]) ? raw["技能"].map(function (skill) { return str(skill); }).filter(Boolean) : [],
        twoHanded: raw["双手"] === true
      };
    }

    function skills() {
      var raw = currentStat && currentStat["技能"];
      return Array.isArray(raw) ? raw.filter(function (skill) { return skill !== ARRAY_META; }) : [];
    }

    function skillView(index) {
      var raw = skills()[index];
      if (typeof raw === "string") {
        var legacy = SKILL_DATA[raw] || {};
        return { index: index, name: raw, rank: rankLabel(legacy.rank), effect: legacy.effect || "未记录效果", description: legacy.description || "尚未记录技能描述。" };
      }
      var name = str(raw && raw["名称"], "未命名技能");
      var fallback = SKILL_DATA[name] || {};
      return {
        index: index,
        name: name,
        rank: rankLabel(raw && raw["位阶"] || fallback.rank),
        effect: str(raw && raw["效果"], fallback.effect || "未记录效果"),
        description: str(raw && raw["描述"], fallback.description || "尚未记录技能描述。")
      };
    }

    function tasks() {
      var raw = currentStat && currentStat["任务"];
      if (raw && typeof raw === "object") {
        return Object.keys(raw)
          .filter(function (key) { return key !== "$meta" && raw[key] && typeof raw[key] === "object"; })
          .map(function (key) { return { key: key, raw: raw[key] }; });
      }
      return [];
    }

    function taskView(key) {
      var found = tasks().filter(function (task) { return task.key === key; })[0];
      var raw = found ? found.raw : {};
      return {
        key: key,
        name: str(raw["名称"], "未命名任务"),
        type: str(raw["类型"], "支线"),
        status: str(raw["状态"], "进行中"),
        rank: rankLabel(raw["位阶"]),
        source: str(raw["来源"], "未记录来源"),
        trigger: str(raw["触发条件"], "未记录触发条件"),
        stage: str(raw["阶段"], "未记录阶段"),
        description: str(raw["描述"], "尚未记录任务描述。"),
        completion: str(raw["完成条件"], "未记录完成条件。"),
        progress: str(raw["当前进度"], "未记录进度"),
        reward: str(raw["奖励"], "未记录奖励"),
        failure: str(raw["失败影响"], "未记录失败影响"),
        settled: raw["是否已结算"] === true,
        settlement: str(raw["结算记录"], "")
      };
    }

    function renderTaskPane() {
      var list = $("ehx-task-list");
      var detail = $("ehx-task-detail");
      if (!list || !detail) return;
      var all = tasks();
      if (!all.length) {
        clear(list);
        clear(detail);
        list.appendChild(el("div", "ehx-empty", "当前没有任务"));
        detail.appendChild(el("div", "ehx-gear-empty", "接到委托或确定目标后会显示在这里"));
        return;
      }
      if (!all.some(function (task) { return task.key === taskState.selectedKey; })) {
        taskState.selectedKey = all[0] ? all[0].key : "";
      }
      clear(list);
      all.forEach(function (entry) {
        var task = taskView(entry.key);
        var item = el("div", "ehx-gear-item ehx-task-item" + (entry.key === taskState.selectedKey ? " on" : ""));
        item.title = task.name + " · " + task.status;
        item.tabIndex = 0;
        item.setAttribute("role", "button");
        var copy = el("div", "ehx-task-item-main");
        copy.appendChild(el("b", null, task.name));
        copy.appendChild(el("span", "ehx-task-item-sub", task.stage + " · " + task.progress));
        item.appendChild(copy);
        var meta = el("div", "ehx-rel-item-meta ehx-task-item-meta");
        var badge = el("span", "ehx-rel-badge ehx-rank-chip", task.rank);
        badge.setAttribute("data-rank", task.rank);
        meta.appendChild(badge);
        meta.appendChild(el("span", "ehx-rel-badge", task.status));
        item.appendChild(meta);
        item.addEventListener("click", function () {
          taskState.selectedKey = entry.key;
          renderTaskPane();
        });
        item.addEventListener("keydown", function (event) {
          if (event.key === "Enter" || event.key === " ") {
            event.preventDefault();
            taskState.selectedKey = entry.key;
            renderTaskPane();
          }
        });
        list.appendChild(item);
      });

      var selected = taskView(taskState.selectedKey);
      clear(detail);
      var head = el("div", "ehx-gear-head ehx-task-head");
      head.appendChild(el("div", "ehx-gear-mark", selected.name.slice(0, 1)));
      var copy = el("div", "ehx-gear-headcopy");
      copy.appendChild(el("b", null, selected.name));
      copy.appendChild(el("span", null, selected.type + " · " + selected.status + " · 位阶 " + selected.rank + " · " + selected.stage + " · " + selected.progress));
      head.appendChild(copy);
      var actions = el("div", "ehx-gear-actions ehx-task-actions");
      var progress = el("button", "ehx-mini", "推进");
      progress.type = "button";
      progress.addEventListener("click", function () { fillInput("[推进任务 " + selected.name + "]", "任务推进"); });
      actions.appendChild(progress);
      var complete = el("button", "ehx-mini", "完成结算");
      complete.type = "button";
      complete.disabled = selected.status === "已完成" || selected.status === "失败" || selected.settled;
      complete.addEventListener("click", function () { settleTask(taskState.selectedKey, complete); });
      actions.appendChild(complete);
      var fail = el("button", "ehx-mini", "标记失败");
      fail.type = "button";
      fail.disabled = selected.status === "已完成" || selected.status === "失败";
      fail.addEventListener("click", function () { failTask(taskState.selectedKey, fail); });
      actions.appendChild(fail);
      var remove = el("button", "ehx-mini ehx-task-delete", "删除");
      remove.type = "button";
      remove.title = "从任务栏删除此任务";
      remove.setAttribute("aria-label", "删除任务 " + selected.name);
      var resetDelete = 0;
      remove.addEventListener("click", function () {
        if (remove.getAttribute("data-confirm") !== "1") {
          remove.setAttribute("data-confirm", "1");
          remove.textContent = "确认删除";
          remove.classList.add("confirm");
          resetDelete = window.setTimeout(function () {
            if (!remove.isConnected) return;
            remove.removeAttribute("data-confirm");
            remove.textContent = "删除";
            remove.classList.remove("confirm");
          }, 3000);
          return;
        }
        window.clearTimeout(resetDelete);
        deleteTask(taskState.selectedKey, remove);
      });
      actions.appendChild(remove);
      head.appendChild(actions);
      detail.appendChild(head);
      var fields = el("div", "ehx-gear-fields ehx-task-fields");
      [["任务键", selected.key], ["类型与状态", selected.type + " · " + selected.status], ["来源", selected.source], ["触发条件", selected.trigger], ["阶段", selected.stage], ["描述", selected.description], ["完成条件", selected.completion], ["当前进度", selected.progress], ["奖励", selected.reward], ["失败影响", selected.failure], ["结算记录", selected.settlement]].forEach(function (pair) {
        var wide = ["描述", "完成条件", "当前进度", "奖励", "失败影响", "结算记录"].indexOf(pair[0]) >= 0;
        var field = el("div", "ehx-gear-field ehx-task-field" + (wide ? " wide" : ""));
        field.appendChild(el("strong", null, pair[0]));
        field.appendChild(el("span", null, pair[1]));
        fields.appendChild(field);
      });
      detail.appendChild(fields);
      syncHeight();
    }

    function applyTaskRewards(stat, rewardText) {
      var text = str(rewardText, "");
      var base = stat["基础"] || (stat["基础"] = {});
      var money = text.match(/(\d+)\s*G/i);
      var publicRep = text.match(/明面声望\s*[+＋]?\s*(\d+)/);
      var secretRep = text.match(/暗地声望\s*[+＋]?\s*(\d+)/);
      var experience = text.match(/经验\s*[+＋]?\s*(\d+)/);
      if (money) base["金钱"] = Math.max(0, num(base["金钱"], 0) + Number(money[1]));
      if (publicRep) base["明面声望"] = num(base["明面声望"], 0) + Number(publicRep[1]);
      if (secretRep) base["暗地声望"] = num(base["暗地声望"], 0) + Number(secretRep[1]);
      if (experience) base["经验"] = num(base["经验"], 0) + Number(experience[1]);
    }

    function taskCollection(stat) {
      var raw = stat["任务"];
      if (raw && typeof raw === "object" && !Array.isArray(raw)) return raw;
      stat["任务"] = {};
      return stat["任务"];
    }

    function settleTask(key, button) {
      var selected = taskView(key);
      if (!selected) return false;
      return writeLatest(function (stat) {
        var collection = taskCollection(stat);
        var task = collection[key];
        if (!task) throw new Error("任务不存在");
        if (task["是否已结算"] === true || str(task["状态"], "") === "已完成") throw new Error("任务已经结算，不能重复领取奖励");
        applyTaskRewards(stat, task["奖励"]);
        task["状态"] = "已完成";
        task["当前进度"] = "已完成，奖励已结算";
        task["是否已结算"] = true;
        task["结算记录"] = "已完成并结算：" + str(task["奖励"], "无奖励");
      }, "任务已完成并结算", "[完成并结算 " + selected.name + "]", button);
    }

    function failTask(key, button) {
      var selected = taskView(key);
      if (!selected) return false;
      return writeLatest(function (stat) {
        var collection = taskCollection(stat);
        var task = collection[key];
        if (!task) throw new Error("任务不存在");
        task["状态"] = "失败";
        task["当前进度"] = "任务失败";
      }, "任务已标记失败", "[任务失败 " + selected.name + "]", button);
    }

    function deleteTask(key, button) {
      var selected = taskView(key);
      if (!selected) return false;
      return writeLatest(function (stat) {
        var collection = taskCollection(stat);
        if (!collection[key]) throw new Error("任务不存在");
        delete collection[key];
      }, "任务已删除：" + selected.name, "[删除任务 " + selected.name + "]", button);
    }

    function totalEquipmentBonus(stat, key) {
      var total = 0;
      var equipment = stat && stat["装备"];
      if (!equipment || typeof equipment !== "object") return total;
      Object.keys(equipment).forEach(function (slot) {
        var bonus = equipment[slot] && equipment[slot]["加成"];
        if (!bonus || typeof bonus !== "object") return;
        total += num(bonus[key], 0);
      });
      return total;
    }

    function gearKey(tab, key) { return tab + ":" + key; }

    function joinLook(look, keys) {
      return keys.map(function (key) { return str(look && look[key], ""); }).filter(Boolean).join(" ");
    }

    function overallLook(look) {
      return str(look && look["总体描述"], "")
        || joinLook(look, LOOK_FACE.concat(LOOK_BODY))
        || "尚未记录总体描述。";
    }

    function setTab(id) {
      activeTab = id;
      var tabs = Array.prototype.slice.call(document.querySelectorAll("#" + ROOT_ID + " .ehx-tab"));
      var panes = Array.prototype.slice.call(document.querySelectorAll("#" + ROOT_ID + " .ehx-pane"));
      tabs.forEach(function (tab) {
