        tab.className = "ehx-tab" + (on ? " on" : "");
        tab.setAttribute("aria-selected", on ? "true" : "false");
      });
      panes.forEach(function (pane) {
        var on = pane.getAttribute("data-pane") === id;
        pane.className = "ehx-pane" + (on ? " on" : "");
