    function tip(message) {
      var node = $("ehx-tip");
      if (!node) return;
      node.textContent = message;
      window.setTimeout(function () {
        if (node.textContent === message) node.textContent = "";
      }, 3200);
    }

    function fillInput(text, message) {
      try {
        var doc = window.parent && window.parent.document;
        var area = doc && doc.getElementById("send_textarea");
        if (area) {
          area.value = text;
          area.dispatchEvent(new Event("input", { bubbles: true }));
          try { area.focus(); } catch (e) {}
          tip(message + "（已填入输入栏）");
          return true;
        }
      } catch (e) {}
      try {
        if (window.TavernHelper && typeof window.TavernHelper.triggerSlash === "function") {
          window.TavernHelper.triggerSlash("/setinput " + text.replace(/\n/g, "\\n"));
          tip(message + "（已填入输入栏）");
          return true;
        }
      } catch (e) {}
      tip("未能直接写入，请手动操作：" + text);
      return false;
    }

    // 关系人物的装备 / 技能清单：每条一张小卡，标题带位阶徽章，下面写效果与描述。
    function relationHoldingsBlock(title, list, emptyText) {
      var wrap = el("div");
      wrap.appendChild(el("div", "ehx-rel-section-title", title));
      var items = Array.isArray(list) ? list : [];
      if (!items.length) {
        wrap.appendChild(el("div", "ehx-rel-holding-empty", emptyText));
        return wrap;
      }
      var grid = el("div", "ehx-rel-holdings");
      items.forEach(function (item) {
        var card = el("div", "ehx-rel-holding");
        var head = el("div", "ehx-rel-holding-head");
        var chip = el("span", "ehx-rel-badge ehx-rank-chip", item["位阶"]);
        chip.setAttribute("data-rank", item["位阶"]);
        head.appendChild(chip);
        head.appendChild(el("b", null, item["名称"]));
        card.appendChild(head);
        card.appendChild(el("div", "ehx-rel-holding-effect", "效果：" + item["效果"]));
        card.appendChild(el("div", "ehx-rel-holding-desc", item["描述"]));
        grid.appendChild(card);
      });
      wrap.appendChild(grid);
      return wrap;
    }

    // 关系人物的装备/技能统一成 {名称, 位阶, 效果, 描述}；旧存档里的纯字符串照常显示。
    function relationHoldings(list) {
      if (!Array.isArray(list)) return [];
      return list.filter(function (raw) { return raw !== ARRAY_META; }).map(function (raw) {
        if (raw && typeof raw === "object") {
          return {
            名称: str(raw["名称"], "未命名"),
            位阶: rankLabel(raw["位阶"]),
            效果: str(raw["效果"], "未记录效果。"),
            描述: str(raw["描述"], "尚未记录描述。")
          };
        }
        return { 名称: str(raw, "未命名"), 位阶: rankLabel(), 效果: "未记录效果。", 描述: "尚未记录描述。" };
      });
    }

    function personFrom(kind, index) {
      var groups = currentStat && currentStat["关系"] ? currentStat["关系"] : {};
      var list = Array.isArray(groups[kind]) ? groups[kind] : [];
      var person = list[index] || {};
      return {
        kind: kind,
        index: index,
        name: str(person["名字"], "未知人物"),
        identity: str(person["身份"], person["一句话"] || "身份未明"),
        identityLabel: str(person["身份标签"], ""),
        rank: rankLabel(person["位阶"]),
        affinity: clamp(num(person["好感"], 10), 0, 100),
        present: person["在场"] === true,
        gender: str(person["性别"], ""),
        appearance: str(person["外貌"], "尚未记录外貌。"),
        body: str(person["身材"], "尚未记录身材。"),
        clothing: str(person["穿着"], "尚未记录穿着。"),
        nsfw: person["NSFW状态"] && typeof person["NSFW状态"] === "object" ? person["NSFW状态"] : {},
        level: num(person["等级"], 1),
        stats: person["属性"] || { "力量": 5, "敏捷": 5, "魔力": 5, "幸运": 5 },
        equipment: relationHoldings(person["装备"]),
        skills: relationHoldings(person["技能"]),
        avatar: readCustomAvatar(kind, str(person["名字"], "")) ||
          (safeAvatarSource(person["头像"]) && !isManagedDefaultAvatar(person["头像"]) ? safeAvatarSource(person["头像"]) : "") ||
          DEFAULT_RELATION_AVATARS[str(person["名字"], "")] ||
          "",
        raw: person
      };
    }

    function personActionButton(label, kind, index, delta, fallback) {
      var button = el("button", "ehx-mini", label);
      button.type = "button";
      button.addEventListener("click", function (event) {
        event.preventDefault();
        event.stopPropagation();
        writeAffinity(kind, index, delta, fallback, button);
      });
      return button;
    }

    function personKey(kind, index) { return kind + ":" + index; }

    function rosterRecords() {
      var groups = currentStat && currentStat["关系"] ? currentStat["关系"] : {};
      var result = [];
      var seen = {};
      [["名册", "名册"], ["固定", "旧名册"], ["其他", "旧名册"]].forEach(function (pair) {
        var kind = pair[0];
        var list = Array.isArray(groups[kind]) ? groups[kind] : [];
        list.forEach(function (raw, index) {
          if (!raw || raw === ARRAY_META || typeof raw !== "object") return;
          var name = str(raw["名字"], "");
          if (!name || seen[name]) return;
          seen[name] = true;
          result.push({ kind: kind, index: index, sourceLabel: pair[1] });
        });
      });
      return result;
    }

    function allPeople() {
      return rosterRecords().map(function (row) { return personFrom(row.kind, row.index); });
    }

    function visiblePeople(people) {
      var query = relationState.query.trim().toLowerCase();
      return people.filter(function (person) {
        if (relationState.filter === "在场" && !person.present) return false;
        if (relationState.filter === "不在场" && person.present) return false;
        if (relationState.filter === "女性" && person.gender !== "女") return false;
        if (!query) return true;
        return (person.name + " " + person.identity + " " + person.identityLabel).toLowerCase().indexOf(query) !== -1;
      });
    }

    function relationKindLabel(person) {
      return person.kind === "名册" ? "开放名册" : "旧存档名册";
    }

    function relationCompleteness(person) {
      var raw = person.raw || {};
      var values = [
        person.name,
        person.identity,
        person.identityLabel,
        raw["位阶"],
        person.gender,
        person.appearance,
        person.body,
        person.clothing,
        Number(person.level) > 0 ? String(person.level) : ""
      ];
      ["力量", "敏捷", "魔力", "幸运"].forEach(function (key) {
        values.push(Number(person.stats && person.stats[key]) > 0 ? String(person.stats[key]) : "");
      });
      if (person.gender === "女") {
        ["嘴唇", "胸部", "阴部", "臀部", "肛门", "子宫"].forEach(function (key) {
          values.push(person.nsfw[key]);
        });
      }
      values.push(Array.isArray(person.equipment) && person.equipment.length ? "equipment" : "");
      values.push(Array.isArray(person.skills) && person.skills.length ? "skills" : "");
      var filled = values.filter(function (value) {
        return value && !/尚未记录/.test(String(value));
      }).length;
      return Math.round((filled / values.length) * 100);
    }

    function personArchivePrompt(person) {
      var path = "/关系/" + person.kind + "/" + person.index;
      return [
        "[补全人物档案 " + person.name + "]",
        "请先读取卡内与该角色相关的世界书人物条目和当前剧情，然后对 " + path + " 做一次全量人物变量更新。",
        "必须完整覆盖：名字、身份、身份标签、位阶、好感、标签、性别、在场、外貌、身材、穿着、等级、四项属性、装备、技能" + (person.gender === "女" ? "、NSFW 状态六项" : "") + "。",
        "装备与技能必须使用名称、位阶、效果、描述；不要只改一个字段，也不要把未发生变化的字段留成空值。更新后保持当前好感、在场和剧情连续性。"
      ].join("\n");
