    function deletePerson(kind, index, button) {
      var person = personFrom(kind, index);
      return writeLatest(function (stat) {
        var list = stat["关系"] && stat["关系"][kind];
        if (!Array.isArray(list) || !list[index]) throw new Error("人物档案不存在");
        list.splice(index, 1);
      }, "人物已从关系名册删除：" + person.name, null, button).then(function (ok) {
        if (ok) relationState.selectedKey = "";
        return ok;
      });
