        filters.appendChild(button);
      });
      var search = $("ehx-rel-search");
      if (search && search.value !== relationState.query) search.value = relationState.query;
      var people = visiblePeople(all);
      if (!people.some(function (person) { return personKey(person.kind, person.index) === relationState.selectedKey; })) {
        relationState.selectedKey = people[0] ? personKey(people[0].kind, people[0].index) : "";
      }
      renderRelationList(people);
      renderRelationDetail();
      syncHeight();
    }

    function renderGearList() {
      var list = $("ehx-gear-list");
      clear(list);
      var rows = [];
      if (gearState.tab === "装备") {
        SLOTS.forEach(function (slot) {
          var raw = currentStat["装备"] && currentStat["装备"][slot];
          var name = str(raw && raw["名称"], defaultEquipName(slot));
          var current = equipFor(slot, name);
          rows.push({ key: "装备:" + slot, title: slot, subtitle: name, rank: current["位阶"], count: "" });
        });
      } else if (gearState.tab === "物品") {
        ["装备", "道具", "杂物"].forEach(function (category) {
          var matches = [];
          items().forEach(function (_, index) {
            var item = itemView(index);
            if (item.category === category) matches.push({ index: index, item: item });
          });
          if (!matches.length) return;
          rows.push({ heading: category + " · " + matches.length });
          matches.forEach(function (entry) {
            rows.push({ key: "物品:" + entry.index, title: entry.item.name, subtitle: entry.item.effect, rank: entry.item.rank, count: "x" + entry.item.quantity });
          });
        });
      } else {
        skills().forEach(function (_, index) {
          var skill = skillView(index);
          rows.push({ key: "技能:" + index, title: skill.name, subtitle: skill.effect, rank: skill.rank, count: "" });
        });
      }
      if (!rows.length) {
        gearState.selectedKey = gearState.tab === "物品" ? "物品:0" : (gearState.tab === "技能" ? "技能:0" : "");
        list.appendChild(el("div", "ehx-empty", gearState.tab === "物品" ? "物品栏为空" : "暂无条目"));
        return;
      }
      if (!rows.some(function (row) { return row.key === gearState.selectedKey; })) {
        gearState.selectedKey = rows[0].key;
      }
      rows.forEach(function (row) {
        if (row.heading) {
          list.appendChild(el("div", "ehx-gear-heading", row.heading));
          return;
        }
        var item = el("div", "ehx-gear-item" + (row.key === gearState.selectedKey ? " on" : ""));
        item.tabIndex = 0;
        item.setAttribute("role", "button");
        var copy = el("div");
        copy.appendChild(el("b", null, row.title));
        copy.appendChild(el("span", null, row.subtitle));
        item.appendChild(copy);
        var meta = el("div", "ehx-rel-item-meta");
        if (row.count) meta.appendChild(el("span", "ehx-gear-count", row.count));
        item.appendChild(meta);
        item.addEventListener("click", function () {
          gearState.selectedKey = row.key;
          renderGearPane();
        });
        item.addEventListener("keydown", function (event) {
          if (event.key === "Enter" || event.key === " ") {
            event.preventDefault();
            gearState.selectedKey = row.key;
            renderGearPane();
          }
        });
        list.appendChild(item);
      });
    }

    // 主加成（基础属性 / HP / MP）与次要加成（气质 / 情欲）分开返回，面板分两块显示。
    function bonusParts(bonus) {
      var primary = [];
      var secondary = [];
      if (!bonus || typeof bonus !== "object") return { primary: "", secondary: "" };
      BONUS_ORDER.forEach(function (key) {
        if (!BONUS_TARGET[key]) return;
        var value = num(bonus[key], 0);
        if (!value) return;
        var text = (BONUS_LABEL[key] || key) + " " + (value > 0 ? "+" : "−") + Math.abs(value);
        (BONUS_PRIMARY[key] ? primary : secondary).push(text);
      });
      return { primary: primary.join(" · "), secondary: secondary.join(" · ") };
    }

    function gearDetailFields(title, name, effect, description, meta, rank, bonus, skills) {
      var detail = $("ehx-gear-detail");
      clear(detail);
      var head = el("div", "ehx-gear-head");
      head.appendChild(el("div", "ehx-gear-mark", name.slice(0, 1)));
      var copy = el("div", "ehx-gear-headcopy");
      copy.appendChild(el("b", null, name));
      copy.appendChild(el("span", null, "位阶 " + rankLabel(rank) + " · " + meta));
      head.appendChild(copy);
      var actions = el("div", "ehx-gear-actions");
      head.appendChild(actions);
      detail.appendChild(head);
      var fields = el("div", "ehx-gear-fields");
      var pairs = [];
      if (str(effect)) pairs.push(["效果", effect]);
      pairs.push(["描述", description]);
      var bonusText = bonusParts(bonus);
      if (bonusText.primary) pairs.push(["加成", bonusText.primary]);
      if (bonusText.secondary) pairs.push(["次要加成", bonusText.secondary]);
      if (Array.isArray(skills) && skills.length) pairs.push(["附带技能", skills.join(" / ")]);
      pairs.forEach(function (pair) {
        var field = el("div", "ehx-gear-field");
        field.appendChild(el("strong", null, title + " · " + pair[0]));
        field.appendChild(document.createTextNode(pair[1]));
        fields.appendChild(field);
      });
      detail.appendChild(fields);
      return { detail: detail, actions: actions };
    }

    function renderGearDetail() {
      var detail = $("ehx-gear-detail");
      var key = gearState.selectedKey || "";
      var parts = key.split(":");
      var type = parts[0];
      var value = parts.slice(1).join(":");
      if (type === "装备") {
        var slot = value || SLOTS[0];
        var raw = currentStat["装备"] && currentStat["装备"][slot];
        var current = equipFor(slot, raw && raw["名称"] ? raw["名称"] : defaultEquipName(slot));
        var built = gearDetailFields("装备", current["名称"], current["效果"], current["描述"], "槽位 · " + slot, current["位阶"], current["加成"], current["技能"]);
        var picker = el("div", "ehx-gear-picker");
        var select = el("select");
        equipmentOptions(slot).forEach(function (option) {
          var node = el("option", null, option["名称"]);
          node.value = option["名称"];
          if (option["名称"] === current["名称"]) node.selected = true;
          select.appendChild(node);
        });
        select.addEventListener("change", function () {
          writeEquipment(slot, select.value, select);
        });
        // 双手武器占满主手时，副手整体不可用：选择器与脱下按钮一起置灰。
        var mainHand = currentStat["装备"] && currentStat["装备"]["主手"];
        var offhandLocked = slot === "副手" && mainHand && mainHand["双手"] === true;
        if (offhandLocked) {
          select.disabled = true;
          select.title = "主手正在使用双手武器，暂时无法装备副手";
        }
        var off = el("button", "ehx-mini", "脱下");
        off.type = "button";
        if (offhandLocked) {
          off.disabled = true;
          off.title = "主手正在使用双手武器，暂时无法操作副手";
        }
        off.addEventListener("click", function () { unequipSlot(slot, off); });
        picker.appendChild(select);
        picker.appendChild(off);
        built.detail.appendChild(picker);
        if (offhandLocked) {
          var lockNote = el("div", "ehx-note", "双手武器占用主手，副手栏暂时锁定；卸下双手武器后即可装备副手。");
          built.detail.appendChild(lockNote);
        }
        return;
      }
      if (type === "物品") {
        var index = num(value, 0);
        var itemList = items();
        if (!itemList[index]) {
          clear(detail);
          detail.appendChild(el("div", "ehx-gear-empty", "物品栏为空"));
          return;
        }
        var item = itemView(index);
        var slotText = item.slot ? " · 槽位 " + item.slot : "";
        var builtItem = gearDetailFields("物品", item.name, item.effect, item.description, "背包 · " + item.category + slotText + " · 数量 " + item.quantity, item.rank, item.bonus, item.skills);
        if (item.category === "装备" && item.slot) {
          var equip = el("button", "ehx-mini", "穿戴");
          equip.type = "button";
          equip.addEventListener("click", function () { equipInventoryItem(index, equip); });
          builtItem.actions.appendChild(equip);
        }
        var use = el("button", "ehx-mini", "使用");
        use.type = "button";
        use.disabled = item.quantity <= 0 || item.category === "装备";
        use.addEventListener("click", function () { useItem(index, use); });
        builtItem.actions.appendChild(use);
        return;
      }
      if (type === "技能") {
        var skillIndex = num(value, 0);
        if (!skills()[skillIndex]) {
          clear(detail);
          detail.appendChild(el("div", "ehx-gear-empty", "暂无技能"));
          return;
        }
        var skill = skillView(skillIndex);
        var builtSkill = gearDetailFields("技能", skill.name, skill.effect, skill.description, "技能", skill.rank);
        var cast = el("button", "ehx-mini", "使用技能");
        cast.type = "button";
        cast.addEventListener("click", function () { fillInput("[使用 " + skill.name + "]", "技能 " + skill.name); });
        builtSkill.actions.appendChild(cast);
        return;
      }
      clear(detail);
      detail.appendChild(el("div", "ehx-gear-empty", "选择左侧条目查看详情"));
    }

    function renderGearPane() {
      Array.prototype.forEach.call(document.querySelectorAll("#" + ROOT_ID + " .ehx-gear-tab"), function (tab) {
        tab.className = "ehx-gear-tab" + (tab.getAttribute("data-gear-tab") === gearState.tab ? " on" : "");
      });
