    function writeLatest(mutator, successMessage, fallbackText, button) {
      pendingWrites += 1;
      try { window.__ehxWritePending = pendingWrites; } catch (_) {}
      if (button) button.disabled = true;
      var operation = writeQueue.then(async function () {
        try {
          var api = await waitForMvu();
          if (!api || typeof api.getMvuData !== "function" || typeof api.replaceMvuData !== "function") {
            throw new Error("MVU 写入接口未就绪");
          }
          var data = api.getMvuData(option());
          if (!data || !data.stat_data) throw new Error("未读到最新楼变量");
          var next = clone(data);
          mutator(next.stat_data);
          syncEquipSkills(next.stat_data);
          await api.replaceMvuData(next, option());
          currentStat = next.stat_data;
          try { window.__ehxCurrentStatData = currentStat; } catch (e) {}
          render();
          tip(successMessage);
          return true;
        } catch (error) {
          try {
            window.__ehxLastWriteError = String(error && (error.stack || error.message) || error);
            console.error("[艾迪娜 HUD] 变量写入失败", error);
          } catch (_) {}
          tip("变量写入失败，已退回输入栏");
          if (fallbackText) fillInput(fallbackText, "写入失败");
          return false;
        } finally {
          if (button && button.isConnected) button.disabled = false;
        }
      });
      writeQueue = operation.catch(function () { return false; });
      return operation.finally(function () {
        pendingWrites = Math.max(0, pendingWrites - 1);
        try { window.__ehxWritePending = pendingWrites; } catch (_) {}
      });
    }

    function writeAffinity(kind, index, delta, fallback, button) {
      var person = personFrom(kind, index);
      return writeLatest(function (stat) {
        var list = stat["关系"] && stat["关系"][kind];
        if (!Array.isArray(list) || !list[index]) throw new Error("人物档案不存在");
        var oldValue = clamp(num(list[index]["好感"], 10), 0, 100);
        list[index]["好感"] = clamp(oldValue + delta, 0, 100);
      }, person.name + " 好感已写入（" + (delta > 0 ? "+5" : "-5") + "）",
      "[好感 " + person.name + " " + (delta > 0 ? "+5" : "-5") + "]", button);
    }

    function writeEquipment(slot, name, button) {
      return writeLatest(function (stat) {
        if (!stat["装备"] || typeof stat["装备"] !== "object") stat["装备"] = {};
        if (!Array.isArray(stat["物品栏"])) stat["物品栏"] = [];
        var currentItem = stat["装备"][slot];
        var fromInventoryIndex = -1;
        for (var i = 0; i < stat["物品栏"].length; i += 1) {
          var candidate = stat["物品栏"][i];
          if (!candidate || candidate === ARRAY_META || typeof candidate !== "object") continue;
          if (normalizeItemCategory(candidate["类别"]) !== "装备") continue;
          if (str(candidate["槽位"], "") !== slot) continue;
          if (str(candidate["名称"], "") !== name) continue;
          fromInventoryIndex = i;
          break;
        }
        var item = fromInventoryIndex >= 0
          ? inventoryItemToEquip(stat["物品栏"][fromInventoryIndex], slot)
          : equipFor(slot, name);
        if (!isDefaultEquipment(slot, currentItem) && str(currentItem["名称"], "") !== item["名称"]) {
          addEquipmentToInventory(stat, slot, currentItem);
        }
        if (fromInventoryIndex >= 0) {
          var raw = stat["物品栏"][fromInventoryIndex];
          var quantity = Math.max(1, num(raw["数量"], 1)) - 1;
          if (quantity <= 0) stat["物品栏"].splice(fromInventoryIndex, 1);
          else raw["数量"] = quantity;
        }
        stat["装备"][slot] = item;
        // 双手武器占满主手时，副手必须一起清空。
        if (slot === "主手" && item["双手"]) {
          var offhand = stat["装备"]["副手"];
          if (offhand && str(offhand["名称"]) && str(offhand["名称"]) !== "无") {
            addEquipmentToInventory(stat, "副手", offhand);
            stat["装备"]["副手"] = defaultEquip("副手");
          }
        }
        syncEquipSkills(stat);
      }, slot + "已更换为" + name, "[穿戴 " + name + "]", button);
    }

    function unequipSlot(slot, button) {
      return writeEquipment(slot, defaultEquipName(slot), button);
    }

    function equipInventoryItem(index, button) {
      var item = itemView(index);
      if (item.category !== "装备" || !item.slot) {
        tip("这件物品没有可穿戴槽位");
        return false;
      }
      return writeEquipment(item.slot, item.name, button);
    }

    function useItem(index, button) {
      var item = itemView(index);
      return writeLatest(function (stat) {
        var list = Array.isArray(stat["物品栏"]) ? stat["物品栏"] : [];
        var raw = list[index];
        if (!raw) throw new Error("物品不存在");
        var name = str(raw["名称"], item.name);
        if (name === "圣水吊坠") {
          var base = stat["基础"] || (stat["基础"] = {});
          base["魔力"] = Math.min(num(base["魔力上限"], 100), num(base["魔力"], 0) + 10);
        } else if (name === "干毛巾") {
          var body = stat["身体"] || (stat["身体"] = {});
          body["圣液"] = "干涸";
        }
        if (name !== "圣水吊坠") {
          var quantity = Math.max(0, num(raw["数量"], 1) - 1);
          if (quantity <= 0) list.splice(index, 1);
          else raw["数量"] = quantity;
        }
      }, "已使用" + item.name, "[使用 " + item.name + "]", button);
    }

