    const rankName = String(rank || '普通').trim();
    const seed = Array.from(name).reduce((sum, char) => sum + char.codePointAt(0), 0);
    const levelBase = levelByRank[rankName] || 5;
    const statBase = statByRank[rankName] || 7;
    const equipmentName = /木剑/.test(ability)
      ? '学徒木剑'
      : /长剑|短剑|佩剑|巨剑|骑士剑/.test(`${ability}\n${content}`)
