          ? '随身法杖'
          : /弓|弩/.test(`${ability}\n${content}`)
            ? '随身短弓'
            : '身份常服';
    const equipmentSlot = /常服/.test(equipmentName) ? '身体' : /弓|弩/.test(equipmentName) ? '主手' : '主手';
    const skillName = /木剑|长剑|短剑|佩剑|巨剑|剑/.test(ability)
