  function detectPersonName(text, patch) {
    const haystack = String(text || '');
    const candidates = EDINA_WORLDBOOK_ENTRIES
      .filter((item) => String(item.comment || '').startsWith('👥人物|'))
      .map((item) => String(item.comment || '').split('-').pop())
      .filter(Boolean)
      .map((name) => ({ name, index: haystack.indexOf(name) }))
      .filter((item) => item.index >= 0)
      .sort((a, b) => a.index - b.index);
    if (candidates.length) return candidates[0].name;
    const namePatch = patch.find((item) => {
      const index = relationIndexFromPath(item.path);
      return index != null && /^\/关系\/名册\/\d+\/名字$/.test(item.path) && typeof item.value === 'string';
    });
    return namePatch ? namePatch.value : '未命名角色';
  }

  function buildPersonRecord(name, patch) {
    const info = knownPersonInfo(name);
    const affinityPatch = patch.find((item) => {
      const index = relationIndexFromPath(item.path);
      return index != null && /^\/关系\/名册\/\d+\/好感$/.test(item.path) && Number.isFinite(Number(item.value));
    });
    const affinity = affinityPatch ? Math.max(0, Math.min(100, Number(affinityPatch.value))) : 10;
    return {
      名字: info.name,
      身份: info.identity,
      身份标签: info.label,
      位阶: info.rank,
      好感: affinity,
      标签: affinity < 20 ? '陌生' : affinity < 40 ? '友善' : affinity < 60 ? '亲密' : affinity < 80 ? '痴迷' : '灵魂绑定',
      在场: true,
      性别: info.gender,
      一句话: '本轮剧情首次登场，关系档案已建立。',
      外貌: info.appearance || '外貌将在后续剧情中继续补充。',
      身材: info.body || '',
      穿着: info.clothing || '',
      NSFW状态: { 嘴唇: '', 胸部: '', 阴部: '', 臀部: '', 肛门: '', 子宫: '', ...(info.nsfw || {}) },
      等级: info.level || 1,
      属性: Object.assign({ 力量: 0, 敏捷: 0, 魔力: 0, 幸运: 0 }, info.stats || {}),
      装备: Array.isArray(info.equipment) ? info.equipment : [],
      技能: Array.isArray(info.skills) ? info.skills : [],
      头像: '',
    };
  }

  function isPlaceholderPersonText(value) {
    const text = String(value == null ? '' : value).trim();
    return !text || /尚未记录|将在后续剧情中继续补充/.test(text);
  }

  function personFieldIsMeaningful(key, value) {
    if (value === undefined || value === null) return false;
    if (key === '好感') return Number.isFinite(Number(value));
    if (key === '在场') return typeof value === 'boolean';
    if (key === '等级') return Number.isFinite(Number(value)) && Number(value) > 0;
    if (key === '属性') return value && typeof value === 'object' && !Array.isArray(value);
    if (key === 'NSFW状态') return value && typeof value === 'object' && !Array.isArray(value);
    if (key === '装备' || key === '技能') return Array.isArray(value) && value.length > 0;
    if (typeof value === 'string') return !isPlaceholderPersonText(value);
    if (Array.isArray(value)) return value.length > 0;
    if (typeof value === 'object') return Object.keys(value).length > 0;
    return true;
  }

  function mergePersonField(record, key, value) {
    if (!personFieldIsMeaningful(key, value)) return record;
    if (key === '头像' && isDefaultRelationAvatar(value)) return record;
    if (key === '属性') {
      const stats = { ...(record[key] || {}) };
      Object.entries(value).forEach(([statName, statValue]) => {
        if (Number.isFinite(Number(statValue)) && Number(statValue) > 0) stats[statName] = Number(statValue);
      });
      record[key] = stats;
      return record;
    }
    if (key === 'NSFW状态') {
      const statuses = { ...(record[key] || {}) };
      Object.entries(value).forEach(([statusName, statusValue]) => {
        if (!isPlaceholderPersonText(statusValue)) statuses[statusName] = statusValue;
      });
      record[key] = statuses;
      return record;
    }
    record[key] = key === '等级' ? Number(value) : value;
    return record;
  }

  function mergeExistingPerson(generated, existing) {
    const merged = generated && typeof generated === 'object' && !Array.isArray(generated) ? { ...generated } : {};
    Object.entries(existing && typeof existing === 'object' && !Array.isArray(existing) ? existing : {})
      .forEach(([key, value]) => mergePersonField(merged, key, value));
    return merged;
  }

  function applyRelationOperation(record, path, op, value) {
    const match = /^\/关系\/名册\/(\d+)(?:\/(.*))?$/.exec(String(path || ''));
    if (!match || !match[2]) {
      if (op === 'replace' && value && typeof value === 'object' && !Array.isArray(value)) {
        return mergeExistingPerson(record, value);
      }
      return record;
    }
    const segments = match[2].split('/').filter(Boolean);
    let current = record;
    for (let index = 0; index < segments.length - 1; index += 1) {
      const key = segments[index];
      if (!current[key] || typeof current[key] !== 'object') {
        current[key] = /^\d+$/.test(segments[index + 1]) ? [] : {};
      }
      current = current[key];
    }
    const last = segments[segments.length - 1];
    if (op === 'remove') {
      if (Array.isArray(current) && /^\d+$/.test(last)) current.splice(Number(last), 1);
      else delete current[last];
    } else if (Array.isArray(current) && (last === '-' || /^\d+$/.test(last))) {
      if (last === '-') current.push(value);
      else current[Number(last)] = value;
    } else if (op === 'replace') {
      mergePersonField(current, last, value);
    } else {
      current[last] = value;
    }
    return record;
  }

  function expandExistingPerson(record, operations) {
    const name = String(record && record['名字'] || '');
    let merged = mergeExistingPerson(buildPersonRecord(name, operations), record);
    operations.forEach((item) => {
      merged = applyRelationOperation(merged, item.path, item.op, item.value);
    });
    return merged;
  }

  function repairRelationshipPatches(patch, statData, analysis) {
    const roster = getRoster(statData);
    const rosterLength = Array.isArray(roster) ? roster.length : 0;

    const explicitAdds = patch.filter((item) => item && item.op === 'add' && item.path === '/关系/名册/-');
    if (explicitAdds.length && Array.isArray(roster)) {
      const existing = new Map(
        roster
          .map((person, index) => [String(person && person['名字'] || '').trim(), index])
          .filter(([name]) => name),
      );
      const normalized = [];
      let changed = false;
      patch.forEach((item) => {
        if (!item || item.op !== 'add' || item.path !== '/关系/名册/-' || !item.value || typeof item.value !== 'object') {
          normalized.push(item);
          return;
        }
        const explicitName = String(
          item.value['名字']
          || item.value['名称']
          || item.value['姓名']
          || item.value.name
          || '',
        ).trim();
        const inferred = !explicitName || /未命名|未知人物/.test(explicitName)
          ? detectPersonName(analysis, [item])
          : explicitName;
        const canonicalValue = { ...item.value, 名字: inferred };
        if (canonicalValue['好感'] == null && item.value['好感度'] != null) canonicalValue['好感'] = item.value['好感度'];
        if (canonicalValue['标签'] == null && item.value['关系状态'] != null) canonicalValue['标签'] = item.value['关系状态'];
        if (canonicalValue['一句话'] == null && item.value['初遇地点'] != null) canonicalValue['一句话'] = `初遇地点：${item.value['初遇地点']}`;
        const existingIndex = existing.get(inferred);
        if (existingIndex != null) {
          const operation = { op: 'replace', path: `/关系/名册/${existingIndex}`, value: canonicalValue };
          normalized.push({ ...operation, value: expandExistingPerson(roster[existingIndex], [operation]) });
          changed = true;
          return;
        }
        if (!inferred && rosterLength === 1) {
          const currentName = String(roster[0] && roster[0]['名字'] || '').trim();
          if (currentName) {
            const operation = { op: 'replace', path: '/关系/名册/0', value: { ...canonicalValue, 名字: currentName } };
            normalized.push({ ...operation, value: expandExistingPerson(roster[0], [operation]) });
            changed = true;
            return;
          }
        }
        normalized.push({
          ...item,
          value: expandExistingPerson(buildPersonRecord(inferred, [item]), [{
            op: 'replace',
            path: item.path,
            value: canonicalValue,
          }]),
        });
        if (inferred) changed = true;
      });
      if (changed) return { patch: normalized, changed: true };
    }
    const relationOps = patch
      .map((item, index) => ({ item, index, relationIndex: relationIndexFromPath(item.path) }))
      .filter((entry) => entry.relationIndex != null);
    if (!relationOps.length) return { patch, changed: false };

    const existingByIndex = new Map();
    relationOps.forEach((entry) => {
      if (entry.relationIndex >= rosterLength) return;
      if (!existingByIndex.has(entry.relationIndex)) existingByIndex.set(entry.relationIndex, []);
      existingByIndex.get(entry.relationIndex).push(entry.item);
    });
    if (existingByIndex.size) {
      const emitted = new Set();
      const expanded = [];
      patch.forEach((item) => {
        const index = relationIndexFromPath(item && item.path);
        if (index == null || index >= rosterLength) {
          expanded.push(item);
          return;
        }
        if (emitted.has(index)) return;
        emitted.add(index);
        expanded.push({
          op: 'replace',
          path: `/关系/名册/${index}`,
          value: expandExistingPerson(roster[index], existingByIndex.get(index) || []),
        });
      });
      return { patch: expanded, changed: true };
    }

    const firstRelationIndex = relationOps[0].index;
    const missingIndices = [...new Set(
      relationOps
        .filter((entry) => entry.item.op === 'replace' && entry.relationIndex >= rosterLength)
        .map((entry) => entry.relationIndex),
    )].sort((a, b) => a - b);

    if (explicitAdds.length) {
      const withoutAdds = patch.filter((item) => !explicitAdds.includes(item));
      const shift = withoutAdds.findIndex((item) => relationIndexFromPath(item.path) != null);
      const insertAt = shift >= 0 ? shift : withoutAdds.length;
      return {
        patch: [...withoutAdds.slice(0, insertAt), ...explicitAdds, ...withoutAdds.slice(insertAt)],
        changed: true,
      };
    }

    if (!missingIndices.length) return { patch, changed: false };
    const currentName = rosterLength === 1 ? String(roster[0] && roster[0]['名字'] || '').trim() : '';
    const remapped = currentName && missingIndices.length === 1
      ? patch.map((item) => {
        const index = relationIndexFromPath(item && item.path);
        if (index == null || item.op !== 'replace') return item;
        return { ...item, path: String(item.path).replace(/^\/关系\/名册\/\d+/, '/关系/名册/0') };
      })
      : patch;
    if (remapped !== patch) return { patch: remapped, changed: true };

    const additions = [];
    for (let index = rosterLength; index <= missingIndices[missingIndices.length - 1]; index += 1) {
      const patchForIndex = patch.filter((item) => relationIndexFromPath(item.path) === index);
      const name = missingIndices.includes(index)
        ? detectPersonName(analysis, patchForIndex)
        : '未命名角色';
      additions.push({
        op: 'add',
        path: '/关系/名册/-',
        value: buildPersonRecord(name, patchForIndex),
      });
    }
    return {
      patch: [...patch.slice(0, firstRelationIndex), ...additions, ...patch.slice(firstRelationIndex)],
      changed: additions.length > 0,
    };
  }

  function normalizeTaskName(value) {
    return String(value || '').trim().replace(/[「」【】“”"'·、，。！？!?,.\s:_-]/g, '').toLowerCase();
  }

  function parseTaskCommand(text) {
    const source = String(text || '').trim();
    if (!source) return null;
    const complete = source.match(/\[(?:完成并结算|结算任务)\s*([^\]]+?)\s*\]/);
    if (complete) return { type: 'complete', target: complete[1].trim() };
    const progress = source.match(/\[(?:推进任务|更新任务)\s*([^\]]+?)\s*\]/);
    if (progress) return { type: 'progress', target: progress[1].trim() };
    return null;
  }

  function latestUserMessageBefore(chat, messageIndex) {
    if (!Array.isArray(chat)) return '';
    for (let index = Number(messageIndex) - 1; index >= 0; index -= 1) {
      const message = chat[index];
      if (message && message.is_user) return String(message.mes || '');
    }
    return '';
  }

  function taskKeyFromName(value) {
    const name = String(value || '').trim();
    const key = name.replace(/[\/\\{}[\]]/g, '').replace(/\s+/g, ' ').trim();
    return key || '未命名任务';
  }

  function isMeaningfulTaskName(name, key) {
    const value = String(name || '').trim();
    if (!value) return false;
    // 只有键名、没有真实任务名时，常是模型写错键或额外模型补出的半截记录。
    // 纯 ASCII 占位键不允许单独建任务，避免生成幽灵任务。
    if (value === String(key || '').trim() && /^[A-Za-z0-9_-]+$/.test(value)) return false;
    return true;
  }

  function taskRecord(value, key) {
    const source = value && typeof value === 'object' && !Array.isArray(value) ? value : {};
    const output = { ...TASK_DEFAULTS };
    Object.keys(TASK_DEFAULTS).forEach((field) => {
      if (source[field] !== undefined) output[field] = source[field];
    });
    output['名称'] = String(source['名称'] || key || '');
    return output;
  }

  function taskBigrams(value) {
    const source = normalizeTaskName(value).replace(/[任务委托危机主线支线]/g, '');
    const grams = new Set();
    for (let index = 0; index < source.length - 1; index += 1) grams.add(source.slice(index, index + 2));
    return grams;
  }

  function taskAnchorScore(left, right) {
    const leftText = [
      left && left['名称'],
      left && left['来源'],
      left && left['描述'],
      left && left['完成条件'],
      left && left['当前进度'],
    ].filter(Boolean).join(' ');
    const rightText = [
      right && right['名称'],
      right && right['来源'],
      right && right['描述'],
      right && right['完成条件'],
      right && right['当前进度'],
    ].filter(Boolean).join(' ');
    const strong = ['粮仓', '魔蝇', '腐化诱饵', '布雷克', '圣火', '选圣', '遗迹封印'];
    const secondary = ['调查', '账目', '采购', '诱饵', '米蕾', '赛琳', '村民', '教会', '文书', '审讯', '线索', '证据'];
    let score = 0;
    let strongMatched = false;
    strong.forEach((token) => {
      if (leftText.includes(token) && rightText.includes(token)) {
        score += 8;
        strongMatched = true;
      }
    });
    let secondaryMatched = 0;
    secondary.forEach((token) => {
      if (leftText.includes(token) && rightText.includes(token)) {
        score += 2;
        secondaryMatched += 1;
      }
    });
    if (strongMatched && secondaryMatched >= 1) score += 4;
    return score;
  }

  function taskSimilarity(left, right) {
    const leftName = normalizeTaskName(left && left['名称']);
    const rightName = normalizeTaskName(right && right['名称']);
    if (!leftName || !rightName) return 0;
    if (leftName === rightName) return 100;
    const leftGrams = taskBigrams(leftName);
    const rightGrams = taskBigrams(rightName);
    let shared = 0;
    leftGrams.forEach((token) => { if (rightGrams.has(token)) shared += 1; });
    let score = shared * 4;
    if (leftName.includes(rightName) || rightName.includes(leftName)) score += 6;
    if (String(left['来源'] || '').trim() && String(left['来源'] || '').trim() === String(right['来源'] || '').trim()) score += 4;
    if (String(left['类型'] || '').trim() && String(left['类型'] || '').trim() === String(right['类型'] || '').trim()) score += 1;
    const leftContext = taskBigrams([
      left['触发条件'],
      left['描述'],
      left['完成条件'],
    ].filter(Boolean).join(' '));
    const rightContext = taskBigrams([
      right['触发条件'],
      right['描述'],
      right['完成条件'],
    ].filter(Boolean).join(' '));
    let contextShared = 0;
    leftContext.forEach((token) => { if (rightContext.has(token)) contextShared += 1; });
    score += Math.min(8, contextShared);
    score += taskAnchorScore(left, right);
    return score;
  }

  function taskMergeValue(target, source) {
    const output = { ...target };
    Object.keys(source || {}).forEach((key) => {
      const value = source[key];
      if (value === undefined || value === null || value === '') return;
      if (Array.isArray(value) && value.length === 0) return;
      if (value && typeof value === 'object' && !Array.isArray(value) && Object.keys(value).length === 0) return;
      if (key === '是否已结算' && value === true) output[key] = true;
      else if (key === '结算记录') output[key] = [output[key], value].filter(Boolean).filter((item, index, list) => list.indexOf(item) === index).join('；');
      else output[key] = value;
    });
    return output;
  }

  function consolidateTaskCollection(tasks) {
    // 任务表不再做相似度自动合并。不同任务只要没有完全相同的任务键或完整名称，
    // 就必须各自保留，避免一次误匹配把无关任务改写掉。
    return { tasks, changed: false };
  }

  function taskCollection(raw) {
    if (raw && typeof raw === 'object' && !Array.isArray(raw)) {
      return Object.fromEntries(
        Object.entries(raw)
          .filter(([key, value]) => key && key !== '$meta' && value && typeof value === 'object' && !Array.isArray(value))
          .map(([key, value]) => [key, taskRecord(value, key)]),
      );
    }
    return {};
  }

  function findTaskKey(tasks, requestedKey, requestedName) {
    if (requestedKey && tasks[requestedKey]) return requestedKey;
    const requested = normalizeTaskName(requestedName || requestedKey);
    if (!requested) return '';
    const exact = Object.keys(tasks).filter((key) => normalizeTaskName(tasks[key]['名称']) === requested || normalizeTaskName(key) === requested);
    if (exact.length === 1) return exact[0];
    return '';
  }

  function repairTaskPatches(patch, statData) {
    const rawTasks = statData && statData['任务'];
    const initialTasks = taskCollection(rawTasks);
    const consolidated = consolidateTaskCollection(initialTasks);
    const tasks = consolidated.tasks;
    const taskMeta = rawTasks && rawTasks['$meta'] && typeof rawTasks['$meta'] === 'object' ? { $meta: rawTasks['$meta'] } : {};
    const prefix = consolidated.changed ? [{ op: 'replace', path: '/任务', value: { ...taskMeta, ...tasks } }] : [];
    let commandKey = activeTaskCommand && activeTaskCommand.target
      ? findTaskKey(tasks, activeTaskCommand.target, activeTaskCommand.target, {
        名称: activeTaskCommand.target,
        描述: activeTaskCommand.target,
      }, true)
      : '';
    let changed = false;
    const normalized = [];
    patch.forEach((item) => {
      if (!item || typeof item !== 'object' || typeof item.path !== 'string' || !item.path.startsWith('/任务/')) {
        normalized.push(item);
        return;
      }
      const tail = item.path.slice('/任务/'.length);
      const segments = tail.split('/');
      let targetKey = segments.shift() || '';
      const originalKey = targetKey;
      const childPath = segments.length ? `/${segments.join('/')}` : '';
      const wholeRecord = !childPath;
      const requestedName = wholeRecord && item.value && typeof item.value === 'object' && !Array.isArray(item.value)
        ? item.value['名称']
        : targetKey;

      if (!targetKey || targetKey === '-') {
        if (item.op !== 'add' || !item.value || typeof item.value !== 'object' || Array.isArray(item.value)) {
          normalized.push(item);
          return;
        }
        targetKey = taskKeyFromName(item.value['名称']);
      }

      const resolvedKey = commandKey || findTaskKey(
        tasks,
        targetKey,
        requestedName,
        wholeRecord ? item.value : null,
      );
      if (resolvedKey) targetKey = resolvedKey;

      if (item.op === 'add' && wholeRecord && tasks[targetKey]) {
        normalized.push({
          op: 'replace',
          path: `/任务/${targetKey}`,
          value: taskRecord({ ...tasks[targetKey], ...item.value, 名称: item.value['名称'] || tasks[targetKey]['名称'] || targetKey }, targetKey),
        });
        changed = true;
        return;
      }

      if (item.op === 'add' && wholeRecord) {
        if (activeTaskCommand && commandKey) {
          normalized.push({
            op: 'replace',
            path: `/任务/${targetKey}`,
            value: taskRecord({ ...tasks[targetKey], ...item.value, 名称: tasks[targetKey]['名称'] || item.value['名称'] || targetKey }, targetKey),
          });
          changed = true;
          return;
        }
        // 新任务必须带真实名称；只有键名的半截记录不落盘。
        if (!isMeaningfulTaskName(item.value['名称'], targetKey)) return;
        normalized.push({
          op: 'add',
          path: `/任务/${targetKey}`,
          value: taskRecord(item.value, targetKey),
        });
        changed = changed || targetKey !== originalKey;
        return;
      }

      if (wholeRecord && item.op === 'replace') {
        if (!tasks[targetKey]) {
          if (!isMeaningfulTaskName(item.value['名称'], targetKey)) return;
          normalized.push({
            op: 'add',
            path: `/任务/${targetKey}`,
            value: taskRecord(item.value, targetKey),
          });
          changed = true;
          return;
        }
        normalized.push({
          op: 'replace',
          path: `/任务/${targetKey}`,
          value: taskRecord({ ...(tasks[targetKey] || {}), ...item.value, 名称: item.value['名称'] || tasks[targetKey]?.['名称'] || targetKey }, targetKey),
        });
        changed = true;
        return;
      }

      if (childPath && !tasks[targetKey]) {
        // 首次创建事件如果漏写，后续只推进度的补丁仍要落到同一条任务上。
        // 这里用任务键作为临时名称补建，避免把进度写到另一条近似任务。
        if (segments.length === 1 && isMeaningfulTaskName(targetKey, targetKey)) {
          const field = segments[0];
          normalized.push({
            op: 'add',
            path: `/任务/${targetKey}`,
            value: taskRecord({ 名称: targetKey, [field]: item.value }, targetKey),
          });
          changed = true;
        }
        return;
      }
      normalized.push({ ...item, path: `/任务/${targetKey}${childPath}` });
      changed = changed || targetKey !== originalKey;
    });
    if (activeTaskCommand && activeTaskCommand.type === 'complete') {
      if (!commandKey && activeTaskCommand.target) {
        commandKey = findTaskKey(tasks, activeTaskCommand.target, activeTaskCommand.target, {
          名称: activeTaskCommand.target,
          描述: activeTaskCommand.target,
        }, true);
      }
      if (commandKey && tasks[commandKey] && tasks[commandKey]['是否已结算'] !== true) {
        const existingPaths = new Set(normalized.filter((item) => item && typeof item.path === 'string').map((item) => item.path));
        const ensureTaskField = (field, value) => {
          const path = `/任务/${commandKey}/${field}`;
          if (existingPaths.has(path)) return;
          normalized.push({ op: 'replace', path, value });
          existingPaths.add(path);
          changed = true;
        };
        ensureTaskField('状态', '已完成');
        ensureTaskField('当前进度', '已完成，奖励已结算');
        ensureTaskField('是否已结算', true);
        ensureTaskField('结算记录', `已完成并结算：${String(tasks[commandKey]['奖励'] || '奖励已按剧情结算')}`);
      }
    }
    return {
      patch: [...prefix, ...normalized],
      changed: changed || prefix.length > 0,
    };
  }

  function repairEquipmentSkillPatches(patch, statData) {
    const touchesEquipment = patch.some((item) => item && typeof item.path === 'string' && item.path.startsWith('/装备/'));
    const touchesSkills = patch.some((item) => item && typeof item.path === 'string' && item.path.startsWith('/技能'));
    if (!touchesEquipment || touchesSkills) return { patch, changed: false };

    const equipment = statData && statData['装备'];
    if (!equipment || typeof equipment !== 'object' || Array.isArray(equipment)) return { patch, changed: false };
    const wanted = new Map();
    Object.keys(equipment).forEach((slot) => {
      const item = equipment[slot];
      const skills = item && item['技能'];
      if (!Array.isArray(skills)) return;
      skills.forEach((raw) => {
        const name = String(raw || '').trim();
        if (name && !wanted.has(name)) {
          wanted.set(name, {
            slot,
            rank: String(item && item['位阶'] || '普通'),
            equipment: String(item && item['名称'] || '装备'),
          });
        }
      });
    });

    const current = Array.isArray(statData && statData['技能'])
      ? statData['技能'].filter((item) => item !== '$__META_EXTENSIBLE__$')
      : [];
    const desired = current.filter((entry) => {
      if (!entry || typeof entry !== 'object') return true;
      const source = String(entry['来源'] || '');
      return !source.startsWith(EQUIPMENT_SKILL_SOURCE) || wanted.has(String(entry['名称'] || '').trim());
    });

    wanted.forEach((meta, name) => {
      const existing = desired.find((entry) => String(entry && typeof entry === 'object' ? entry['名称'] : entry || '').trim() === name);
      if (existing && typeof existing === 'object') {
        if (!String(existing['来源'] || '').startsWith(EQUIPMENT_SKILL_SOURCE)) return;
        existing['来源'] = EQUIPMENT_SKILL_SOURCE + meta.slot;
        return;
      }
      if (existing) return;
      desired.push({
        ...SKILL_DEFAULTS,
        名称: name,
        位阶: meta.rank,
        效果: '由「' + meta.equipment + '」提供',
        描述: '穿戴「' + meta.equipment + '」期间可用。',
        来源: EQUIPMENT_SKILL_SOURCE + meta.slot,
      });
    });

    if (JSON.stringify(current) === JSON.stringify(desired)) return { patch, changed: false };
    const hasMeta = Array.isArray(statData['技能']) && statData['技能'].includes('$__META_EXTENSIBLE__$');
    return {
      patch: [...patch, { op: 'replace', path: '/技能', value: hasMeta ? [...desired, '$__META_EXTENSIBLE__$'] : desired }],
      changed: true,
    };
  }

  function normalizePatchPaths(patch, statData, analysis) {
    let changed = false;
    const sanitizedInput = patch.filter((item) => {
      const remove = !!item && typeof item.path === 'string' && AGE_PATH_PATTERN.test(item.path);
      if (remove) changed = true;
      return !remove;
    }).map((item) => {
      if (!item || typeof item !== 'object' || item.value === undefined) return item;
      const scrubbed = scrubAgeFields(item.value);
      if (JSON.stringify(scrubbed) === JSON.stringify(item.value)) return item;
      changed = true;
      return { ...item, value: scrubbed };
    });
    const normalized = sanitizedInput.map((item) => {
      if (!item || typeof item !== 'object' || typeof item.op !== 'string' || typeof item.path !== 'string') return item;
      let path = item.path;
      let op = item.op;
      if (path.startsWith('/stat_data/')) path = path.slice('/stat_data'.length);
      path = VARIABLE_PATH_ALIASES[path] || path;
      const appendCollections = ['/临时效果', '/身体改造', '/物品栏', '/战斗/敌人', '/战斗/友方', '/关系/名册', '/技能'];
      if (op === 'replace' && path.endsWith('/-') && appendCollections.includes(path.slice(0, -2))) {
        op = 'add';
      }
      const inventoryIndex = /^\/物品栏\/(\d+)$/.exec(path);
      if (op === 'replace' && inventoryIndex) {
        const inventory = Array.isArray(statData && statData['物品栏']) ? statData['物品栏'] : [];
        if (!inventory[Number(inventoryIndex[1])]) {
          op = 'add';
          path = '/物品栏/-';
        }
      }
      let value = item.value;
      if (op === 'add' && path === '/物品栏/-' && value && typeof value === 'object' && !Array.isArray(value)) {
        const inferredCategory = String(value['槽位'] || '').trim() ? '装备' : '道具';
        const category = ['装备', '道具', '杂物'].includes(value['类别']) ? value['类别'] : inferredCategory;
        value = { ...ITEM_DEFAULTS, 类别: category, ...value };
      } else if (op === 'add' && path === '/战斗/敌人/-' && value && typeof value === 'object' && !Array.isArray(value)) {
        value = { ...ENEMY_DEFAULTS, ...value };
      } else if (op === 'add' && path === '/战斗/友方/-' && value && typeof value === 'object' && !Array.isArray(value)) {
        value = { ...ALLY_DEFAULTS, ...value };
        if (Array.isArray(value['装备'])) {
          value['装备'] = value['装备'].map((entry) => entry && typeof entry === 'object' && !Array.isArray(entry)
            ? { ...ALLY_EQUIPMENT_DEFAULTS, ...entry }
            : entry);
        }
        if (Array.isArray(value['技能'])) {
          value['技能'] = value['技能'].map((entry) => entry && typeof entry === 'object' && !Array.isArray(entry)
            ? { ...ALLY_SKILL_DEFAULTS, ...entry }
            : entry);
        }
      }
      if (path === item.path && op === item.op && value === item.value) return item;
      changed = true;
      return { ...item, op, path, value };
    });
    const repaired = repairRelationshipPatches(normalized, statData, analysis);
    const taskRepaired = repairTaskPatches(repaired.patch, statData);
    const equipmentSkillRepaired = repairEquipmentSkillPatches(taskRepaired.patch, statData);
    const relationAgeCleanup = [];
    const roster = getRoster(statData);
    if (Array.isArray(roster)) {
      roster.forEach((person, index) => {
        if (!person || typeof person !== 'object') return;
        Object.keys(person).forEach((key) => {
          if (AGE_FIELD_PATTERN.test(String(key).trim())) {
            relationAgeCleanup.push({ op: 'remove', path: `/关系/名册/${index}/${key}` });
          }
        });
      });
    }
    return {
      patch: [...relationAgeCleanup, ...equipmentSkillRepaired.patch],
      changed: changed || repaired.changed || taskRepaired.changed || equipmentSkillRepaired.changed || relationAgeCleanup.length > 0,
    };
  }

  function buildVariableBlock(analysis, patch) {
    return [
      '<UpdateVariable>',
      `<Analysis>${String(analysis || '本轮变量已更新。').trim() || '本轮变量已更新。'}</Analysis>`,
      '<JSONPatch>',
      JSON.stringify(patch, null, 2),
      '</JSONPatch>',
      '</UpdateVariable>',
    ].join('\n');
  }

  function normalizeBareArrayInsideUpdateVariable(source, statData) {
    let changed = false;
    const normalized = source.replace(/<UpdateVariable\b[^>]*>([\s\S]*?)<\/UpdateVariable>/gi, (whole, body) => {
      if (/<JSONPatch>/i.test(body)) return whole;
      const segment = findUnwrappedPatch(body, statData);
      if (!segment) return whole;
      const analysis = body.slice(0, segment.start)
        .replace(/<\/(?:Analysis|JSONPatch|UpdateVariable)>/gi, '')
        .trim() || '本轮变量已更新。';
      changed = true;
      return buildVariableBlock(analysis, segment.patch);
    });
    return changed ? normalized : source;
  }

  function normalizeHtmlMvuLog(source, statData) {
    const marker = source.indexOf('[MVU_PATCH_V2]');
    if (marker < 0) return source;
    const divStart = source.lastIndexOf('<div', marker);
    const segmentStart = divStart >= 0 ? divStart : marker;
    const placeholder = source.indexOf('<StatusPlaceHolderImpl', marker);
    const segmentEnd = placeholder >= 0 ? placeholder : source.length;
    const segment = source.slice(segmentStart, segmentEnd);
    const cleaned = segment
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/&nbsp;/gi, ' ')
      .replace(/&quot;/gi, '"')
      .replace(/&#39;|&apos;/gi, "'")
      .replace(/&lt;/gi, '<')
      .replace(/&gt;/gi, '>')
      .replace(/&amp;/gi, '&');
    const segmentPatch = findUnwrappedPatch(cleaned, statData);
    if (!segmentPatch) return source;
    const analysis = (segment.match(/\[Analysis\]\s*([\s\S]*?)(?:<\/div>|<br|$)/i) || [])[1]
      ?.replace(/<[^>]*>/g, '')
      .replace(/&nbsp;/gi, ' ')
      .trim() || '本轮变量已更新。';
    return [
      source.slice(0, segmentStart).trimEnd(),
      '',
      buildVariableBlock(analysis, segmentPatch.patch),
      source.slice(segmentEnd).trimStart(),
    ].join('\n');
  }

  function normalizeStandardVariablePayload(source, statData) {
    if (!/<UpdateVariable>/i.test(source)) return source;
    const sourceAnalysis = (source.match(/<Analysis>([\s\S]*?)<\/Analysis>/i) || [])[1] || '';

    const objectNormalized = source.replace(/<UpdateVariable\b[^>]*>\s*(\{[\s\S]*?\})\s*<\/UpdateVariable>/gi, (whole, body) => {
      let parsed = null;
      try {
        parsed = JSON.parse(String(body || '').trim());
      } catch (_) {
        return whole;
      }
      if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return whole;

      const rawPatch = parsed.patch ?? parsed.jsonPatch ?? parsed.json_patch ?? parsed.JSONPatch;
      const patch = Array.isArray(rawPatch) ? rawPatch : (rawPatch && typeof rawPatch === 'object' ? [rawPatch] : null);
      if (!patch) return whole;

      const analysis = String(
        parsed.analysis
        ?? parsed.Analysis
        ?? parsed['变量分析']
        ?? '本轮变量已更新。'
      ).replace(/<\/(?:Analysis|JSONPatch|UpdateVariable)>/gi, '');
      const normalizedPatch = normalizePatchPaths(patch, statData, analysis).patch
        .filter((item) => item && typeof item === 'object' && typeof item.op === 'string' && typeof item.path === 'string');
      return buildVariableBlock(analysis, normalizedPatch);
    });
    if (objectNormalized !== source) return objectNormalized;

    let changed = false;
    const normalized = source.replace(/<JSONPatch>\s*([\s\S]*?)\s*<\/JSONPatch>/gi, (whole, body) => {
      let parsed = null;
      try {
        parsed = JSON.parse(String(body || '').trim());
      } catch (_) {
        return whole;
      }
      if (!Array.isArray(parsed)) return whole;

      const result = normalizePatchPaths(parsed, statData, sourceAnalysis);
      if (!result.changed) return whole;
      changed = true;
      return ['<JSONPatch>', JSON.stringify(result.patch, null, 2), '</JSONPatch>'].join('\n');
    });
    const bareArrayNormalized = normalizeBareArrayInsideUpdateVariable(normalized, statData);
    return changed || bareArrayNormalized !== normalized ? bareArrayNormalized : source;
  }

  function parsePatchArrayAt(source, start, statData, analysis) {
    let depth = 0;
    let inString = false;
    let escaped = false;
    for (let i = start; i < source.length; i += 1) {
      const char = source[i];
      if (inString) {
        if (escaped) escaped = false;
        else if (char === '\\') escaped = true;
        else if (char === '"') inString = false;
        continue;
      }
      if (char === '"') {
        inString = true;
        continue;
      }
      if (char === '[') depth += 1;
      if (char === ']') {
        depth -= 1;
        if (depth === 0) {
          const text = source.slice(start, i + 1);
          try {
            const parsed = JSON.parse(text);
            if (!Array.isArray(parsed)) return null;
            const validPatch = normalizePatchPaths(parsed, statData, analysis).patch
              .filter((item) => item && typeof item === 'object' && typeof item.op === 'string' && typeof item.path === 'string');
            return validPatch.length ? { start, end: i + 1, patch: validPatch } : null;
          } catch (_) {
            return null;
          }
        }
      }
    }
    return null;
  }

  function findUnwrappedPatch(source, statData) {
    let cursor = source.length;
    while (cursor > 0) {
      const start = source.lastIndexOf('[', cursor - 1);
      if (start < 0) return null;
      const parsed = parsePatchArrayAt(source, start, statData);
      if (parsed) return parsed;
      cursor = start;
    }
    return null;
  }

  function normalizeLegacyVariablePayload(text, statData) {
    const source = String(text || '');
    if (!source) return source;

    const htmlNormalized = normalizeHtmlMvuLog(source, statData);
    if (htmlNormalized !== source) return htmlNormalized;

    const standardNormalized = normalizeStandardVariablePayload(source, statData);
    if (/<UpdateVariable>/i.test(source)) return standardNormalized;

    let changed = false;
    const converted = source.replace(/```(?:json)?\s*([\s\S]*?)```/gi, (whole, body) => {
      let parsed = null;
      try {
        parsed = JSON.parse(String(body || '').trim());
      } catch (_) {
        return whole;
      }
      if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return whole;

      const analysis = String(
        parsed.analysis
        ?? parsed.Analysis
        ?? parsed['变量分析']
        ?? '本轮变量已更新。'
      ).replace(/<\/(?:Analysis|JSONPatch|UpdateVariable)>/gi, '');
      const rawPatch = parsed.patch ?? parsed.jsonPatch ?? parsed.json_patch ?? parsed.JSONPatch;
      const patch = Array.isArray(rawPatch) ? rawPatch : (rawPatch && typeof rawPatch === 'object' ? [rawPatch] : null);
      if (!patch) return whole;

      const validPatch = normalizePatchPaths(patch, statData, analysis).patch
        .filter((item) => item && typeof item === 'object' && typeof item.op === 'string' && typeof item.path === 'string');
      changed = true;
      return buildVariableBlock(analysis, validPatch);
    });
    if (changed) return converted;

    const unwrapped = findUnwrappedPatch(source, statData);
    if (!unwrapped) return source;

    const beforePatch = source.slice(0, unwrapped.start).trimEnd();
    const paragraphStart = Math.max(beforePatch.lastIndexOf('\n\n'), beforePatch.lastIndexOf('\r\n\r\n'));
    const analysis = (paragraphStart >= 0 ? beforePatch.slice(paragraphStart).trim() : '本轮变量已更新。')
      .replace(/<\/(?:Analysis|JSONPatch|UpdateVariable)>/gi, '')
      .trim() || '本轮变量已更新。';
    const body = paragraphStart >= 0 ? beforePatch.slice(0, paragraphStart).trimEnd() : beforePatch;
    const block = [
      '<UpdateVariable>',
      `<Analysis>${analysis}</Analysis>`,
      '<JSONPatch>',
      JSON.stringify(unwrapped.patch, null, 2),
      '</JSONPatch>',
      '</UpdateVariable>',
    ].join('\n');
    return body ? `${body}\n\n${block}` : block;
  }

  function getChatMessageById(messageId) {
    try {
      const host = window.SillyTavern || (parent && parent.SillyTavern);
      const context = host && typeof host.getContext === 'function' ? host.getContext() : null;
      const chat = context && Array.isArray(context.chat) ? context.chat : null;
      const index = Number(messageId);
      if (!chat || !Number.isInteger(index) || index < 0 || index >= chat.length) return null;
      return { chat, index, message: chat[index] };
    } catch (_) {
      return null;
    }
  }

  function getMvuStatData(mvu, messageId) {
    if (!mvu || typeof mvu.getMvuData !== 'function') return null;
    const start = Number(messageId);
    if (Number.isInteger(start) && start >= 0) {
      for (let index = start; index >= 0 && index >= start - 12; index -= 1) {
        try {
          const data = mvu.getMvuData({ type: 'message', message_id: index });
          if (data && data.stat_data && typeof data.stat_data === 'object') return data.stat_data;
        } catch (_) {}
      }
    }
    try {
      const latest = mvu.getMvuData({ type: 'message', message_id: 'latest' });
      if (latest && latest.stat_data && typeof latest.stat_data === 'object') return latest.stat_data;
    } catch (_) {}
    return null;
  }

  const TASK_CHANGE_CUE = /新(?:的|出现)|接到|接受.*(?:委托|请求)|发布.*(?:委托|任务)|明确.*(?:委托|危机|任务|目标)|限期|三天内|报酬|奖励|请.*(?:处理|调查|查清|解决)|必须.*(?:阻止|完成|解决)|推进|进展|完成|结算|失败|交付/;
  const RELATION_CHANGE_CUE = /介绍|自称|名叫|姓名|认识|结识|同行|离开|离队|返回|回来|重逢|道歉|信任|好感|敌意|背叛|结盟|合作|关系/;

  function narrativeText(source) {
    return String(source || '')
      .replace(/<thinking>[\s\S]*?<\/thinking>/gi, '')
      .replace(/<UpdateVariable>[\s\S]*?<\/UpdateVariable>/gi, '')
      .replace(/<StatusPlaceHolderImpl\s*\/?>/gi, '')
      .replace(/<!--[\s\S]*?-->/g, '')
      .trim();
  }

  function hasPatchPath(source, group) {
    const re = new RegExp(`"path"\\s*:\\s*"(?:\\/stat_data)?\\/${group}(?:\\/|")`, 'i');
    return re.test(String(source || ''));
  }

  function repairNeeds(messageText, statData, chat, messageIndex) {
    const source = String(messageText || '');
    const narrative = narrativeText(source);
    const userInput = latestUserMessageBefore(chat, messageIndex);
    const scene = `${userInput}\n${narrative}`;
    const hasVariableBlock = /<UpdateVariable>/i.test(source);
    const hasTaskPatch = hasPatchPath(source, '任务');
    const hasRelationPatch = hasPatchPath(source, '关系');
    const tasks = taskCollection(statData && statData['任务']);
    const roster = getRoster(statData) || [];
    const namedRoster = roster
      .map((person) => String(person && person['名字'] || '').trim())
      .filter((name) => name && !/未命名|未知人物/.test(name));
    const worldbookNames = EDINA_WORLDBOOK_ENTRIES
      .filter((item) => String(item.comment || '').startsWith('👥人物|'))
      .map((item) => String(item.comment || '').split('-').pop().trim())
      .filter(Boolean);
    const missingWorldbookNames = worldbookNames.filter((name) => scene.includes(name) && !namedRoster.includes(name));
    const rosterMentioned = namedRoster.some((name) => scene.includes(name));
    const relationshipCue = RELATION_CHANGE_CUE.test(scene);
    const taskCue = Object.keys(tasks).length > 0
      ? TASK_CHANGE_CUE.test(scene)
      : /明确.*(?:委托|危机|任务|目标)|请.*(?:处理|调查|查清|解决)|限期|报酬|奖励/.test(scene);
    const needRelations = !hasRelationPatch && (missingWorldbookNames.length > 0 || (relationshipCue && rosterMentioned));
    const needTasks = !hasTaskPatch && taskCue;
    return {
      needed: !hasVariableBlock || needTasks || needRelations,
      needTasks: !hasVariableBlock || needTasks,
      needRelations: !hasVariableBlock || needRelations,
      fullRepair: !hasVariableBlock,
      scene,
      missingWorldbookNames,
    };
  }

  function parseStateRepair(text) {
    const source = String(text || '');
    const fenced = source.match(/```(?:json)?\s*([\s\S]*?)```/i);
    const candidate = fenced ? fenced[1] : source;
    const start = candidate.indexOf('{');
    const end = candidate.lastIndexOf('}');
    if (start < 0 || end <= start) return null;
    try {
      const parsed = JSON.parse(candidate.slice(start, end + 1));
      return parsed && typeof parsed === 'object' ? parsed : null;
    } catch (_) {
      return null;
    }
  }

  function mergeNonEmpty(target, source) {
    const output = { ...(target || {}) };
    Object.entries(source || {}).forEach(([key, value]) => {
      if (value === undefined || value === null || value === '') return;
      if (Array.isArray(value) && value.length === 0) return;
      if (value && typeof value === 'object' && !Array.isArray(value) && Object.keys(value).length === 0) return;
      if (value && typeof value === 'object' && !Array.isArray(value) && output[key] && typeof output[key] === 'object' && !Array.isArray(output[key])) {
        output[key] = mergeNonEmpty(output[key], value);
      } else {
        output[key] = value;
      }
    });
    return output;
  }

  const AGE_FIELD_PATTERN = /^(?:\u5e74\u9f84|\u5e74\u9f84\u72b6\u6001|\u5e74\u9f84\u8bf4\u660e|\u5e74\u9f84\u9a8c\u8bc1|\u662f\u5426\u6210\u5e74|\u6210\u5e74|\u672a\u6210\u5e74|\u751f\u65e5|\u51fa\u751f\u65e5\u671f|age|age_status|is_adult|minor|birthday|birth_date)$/i;
  const AGE_PATH_PATTERN = /(?:^|\/)(?:\u5e74\u9f84|\u5e74\u9f84\u72b6\u6001|\u5e74\u9f84\u8bf4\u660e|\u5e74\u9f84\u9a8c\u8bc1|\u662f\u5426\u6210\u5e74|\u6210\u5e74|\u672a\u6210\u5e74|\u751f\u65e5|\u51fa\u751f\u65e5\u671f|age|age_status|is_adult|minor|birthday|birth_date)(?:\/|$)/i;

  function scrubAgeFields(value) {
    if (Array.isArray(value)) return value.map((item) => scrubAgeFields(item));
    if (!value || typeof value !== 'object') return value;
    const output = {};
    Object.entries(value).forEach(([key, item]) => {
      if (AGE_FIELD_PATTERN.test(String(key).trim())) return;
      output[key] = scrubAgeFields(item);
    });
    return output;
  }

  function stateRepairPatch(repair, statData, options) {
    const patch = [];
    if (options.needTasks && Array.isArray(repair && repair.tasks)) {
      const tasks = taskCollection(statData && statData['任务']);
      repair.tasks.forEach((raw) => {
        if (!raw || typeof raw !== 'object') return;
        const rawName = String(raw['名称'] || raw.name || '').trim();
        if (!rawName) return;
        const requestedKey = taskKeyFromName(raw['任务键'] || raw.key || rawName);
        const existingKey = findTaskKey(tasks, requestedKey, rawName, raw, false);
        const recordInput = { ...raw, 名称: rawName };
        delete recordInput['任务键'];
        delete recordInput.key;
        if (existingKey) {
          patch.push({
            op: 'replace',
            path: `/任务/${existingKey}`,
            value: taskRecord(mergeNonEmpty(tasks[existingKey], recordInput), existingKey),
          });
        } else {
          if (!isMeaningfulTaskName(rawName, requestedKey)) return;
          patch.push({
            op: 'add',
            path: `/任务/${requestedKey}`,
            value: taskRecord(recordInput, requestedKey),
          });
        }
      });
    }
    if (options.needRelations && Array.isArray(repair && repair.relations)) {
      const roster = getRoster(statData);
      const existingRoster = Array.isArray(roster) ? roster : [];
      repair.relations.forEach((raw) => {
        if (!raw || typeof raw !== 'object') return;
        const name = String(raw['名字'] || raw.name || '').trim();
        if (!name || /未命名|未知人物/.test(name)) return;
        if (/^(?:管理员修士|教区调查员|管理员|调查员|巡林员|修士|修女|村民|卫兵|骑士|巡骑|路人|侍从|执事|商人|士兵)$/.test(name)) return;
        const relationPatch = scrubAgeFields({ ...raw });
        if (relationPatch['在场'] === undefined && typeof relationPatch['in_scene'] === 'boolean') {
          relationPatch['在场'] = relationPatch['in_scene'];
        }
        delete relationPatch['in_scene'];
        if (relationPatch['在场'] === undefined && relationPatch['in_scene'] === undefined) {
          const scene = String(options.scene || '');
          const nameIndex = scene.indexOf(name);
          const local = nameIndex >= 0
            ? scene.slice(Math.max(0, nameIndex - 120), nameIndex + 260)
            : scene;
          const arriving = /(回到|返回|回来|重逢|出现|来到|赶到|走进|站在|迎面|撞见)/.test(local);
          const leaving = /(离开|离队|离去|告辞|先行|留在|留驻|留守|送走)/.test(local);
          if (arriving && !leaving) relationPatch['在场'] = true;
          else if (leaving && !arriving) relationPatch['在场'] = false;
        }
        const index = existingRoster.findIndex((person) => String(person && person['名字'] || '').trim() === name);
        if (index >= 0) {
          patch.push({
            op: 'replace',
            path: `/关系/名册/${index}`,
            value: mergeNonEmpty(existingRoster[index], { ...relationPatch, 名字: name }),
          });
        } else {
          patch.push({
            op: 'add',
            path: '/关系/名册/-',
            value: mergeNonEmpty(buildPersonRecord(name, []), { ...relationPatch, 名字: name }),
          });
        }
      });
    }
    return patch;
  }

  function parseTaskEvents(source) {
    const events = [];
    const pattern = /<EdinaTaskEvent(?:\s[^>]*)?>([\s\S]*?)<\/EdinaTaskEvent>/gi;
    let match = null;
    while ((match = pattern.exec(String(source || '')))) {
      const fields = {};
      String(match[1] || '').split(/\r?\n/).forEach((line) => {
        const pair = line.match(/^\s*([^:：=]+?)\s*[:：=]\s*(.*?)\s*$/);
        if (pair) fields[pair[1].trim()] = pair[2].trim();
      });
      const pick = (...keys) => keys.map((key) => fields[key]).find((value) => String(value || '').trim()) || '';
      const actionText = pick('动作', '操作', '类型动作', 'action').toLowerCase();
      const action = /失败|fail/.test(actionText)
        ? 'fail'
        : /结算|完成|complete|settle/.test(actionText)
          ? 'complete'
          : /新建|创建|create|add/.test(actionText)
            ? 'create'
            : 'progress';
      const name = pick('名称', '任务名', '标题', 'name');
      const key = taskKeyFromName(pick('任务键', '键', '任务ID', 'key') || name);
      events.push({
        action,
        key,
        name,
        类型: pick('类型', '任务类型') || '支线',
        状态: pick('状态') || (action === 'complete' ? '已完成' : action === 'fail' ? '失败' : '进行中'),
        位阶: pick('位阶', '难度') || '普通',
        来源: pick('来源', '委托方', '发布人'),
        触发条件: pick('触发条件', '触发'),
        描述: pick('描述', '详情', '背景'),
        阶段: pick('阶段', '当前阶段'),
        当前进度: pick('当前进度', '进度', '阶段'),
        完成条件: pick('完成条件', '目标', '执行目标'),
        奖励: pick('奖励', '报酬'),
        失败影响: pick('失败影响', '失败原因', '后果'),
        结算记录: pick('结算', '结算记录', '结果'),
      });
    }
    return events;
  }

  function stripNonCardTaskEvents(source) {
    const pattern = /<EdinaTaskEvent(?:\s[^>]*)?>([\s\S]*?)<\/EdinaTaskEvent>/gi;
    const stripped = String(source || '').replace(pattern, (full, body) => {
      const fields = {};
      String(body || '').split(/\r?\n/).forEach((line) => {
        const pair = line.match(/^\s*([^:：=]+?)\s*[:：=]\s*(.*?)\s*$/);
        if (pair) fields[pair[1].trim()] = pair[2].trim();
      });
      const action = String(fields['动作'] || fields['操作'] || fields['action'] || '').toLowerCase();
      const status = String(fields['状态'] || '');
      const keep = /新建|创建|create|add/.test(action) ||
        /结算|完成|complete|settle/.test(action) ||
        /已完成|待结算|结算/.test(status);
      return keep ? full : '';
    });
    return stripped.replace(/\n{3,}/g, '\n\n').trimEnd();
  }

  function taskRewardPatch(rewardText, statData) {
    const text = String(rewardText || '');
    const patch = [];
    const base = statData && statData['基础'] && typeof statData['基础'] === 'object' ? statData['基础'] : {};
    const money = text.match(/(\d+)\s*(?:G|金币)/i);
    const experience = text.match(/经验\s*(?:[+＋]\s*)?(\d+)/);
    const publicRep = text.match(/明面声望\s*([+＋-]?\s*\d+)/);
    const secretRep = text.match(/暗地声望\s*([+＋-]?\s*\d+)/);
    const numeric = (value) => Number(String(value || '').replace(/[+＋\s]/g, ''));
    if (money) patch.push({ op: 'replace', path: '/基础/金钱', value: Number(base['金钱'] || 0) + Number(money[1]) });
    if (experience) patch.push({ op: 'replace', path: '/基础/经验', value: Number(base['经验'] || 0) + Number(experience[1]) });
    if (publicRep) patch.push({ op: 'replace', path: '/基础/明面声望', value: Number(base['明面声望'] || 0) + numeric(publicRep[1]) });
    if (secretRep) patch.push({ op: 'replace', path: '/基础/暗地声望', value: Number(base['暗地声望'] || 0) + numeric(secretRep[1]) });
    return patch;
  }

  function taskEventPatch(events, statData) {
    const patch = [];
    const tasks = taskCollection(statData && statData['任务']);
    events.forEach((event) => {
      if (!event) return;
      const targetKey = findTaskKey(tasks, event.key, event.name);
      const eventValue = {
        名称: event.name,
        类型: event.类型,
        状态: event.状态,
        位阶: event.位阶,
        来源: event.来源,
        触发条件: event.触发条件,
        描述: event.描述,
        阶段: event.阶段,
        完成条件: event.完成条件,
        当前进度: event.当前进度,
        奖励: event.奖励,
        失败影响: event.失败影响,
        结算记录: event.结算记录,
      };
      if (event.action === 'create') {
        const key = targetKey || event.key || taskKeyFromName(event.name);
        if (!key || !isMeaningfulTaskName(event.name, key)) return;
        if (targetKey) {
          patch.push({
            op: 'replace',
            path: `/任务/${targetKey}`,
            value: taskRecord(mergeNonEmpty(tasks[targetKey], {
              ...eventValue,
              是否已结算: tasks[targetKey]['是否已结算'] === true,
            }), targetKey),
          });
          return;
        }
        patch.push({
          op: 'add',
          path: `/任务/${key}`,
          value: taskRecord({ ...eventValue, 是否已结算: false }, key),
        });
        return;
      }
      if (!targetKey) {
        // 创建漏写后，后续推进事件仍然补建自己的任务，绝不改写其他相似任务。
        if (event.action === 'progress' && isMeaningfulTaskName(event.name, event.key || taskKeyFromName(event.name))) {
          const key = event.key || taskKeyFromName(event.name);
          patch.push({
            op: 'add',
            path: `/任务/${key}`,
            value: taskRecord({
              ...eventValue,
              状态: event.状态 || '进行中',
              当前进度: event.当前进度 || event.阶段 || '已开始',
              是否已结算: false,
            }, key),
          });
        }
        return;
      }
      const current = tasks[targetKey];
      if (event.action === 'complete') {
        if (current['是否已结算'] === true) return;
        patch.push({
          op: 'replace',
          path: `/任务/${targetKey}`,
          value: taskRecord(mergeNonEmpty(current, {
            ...eventValue,
            名称: event.name || current['名称'],
            状态: '已完成',
            当前进度: event.当前进度 || '已完成，奖励已结算',
            是否已结算: true,
            结算记录: event.结算记录 || event.奖励 || '已完成并结算',
          }), targetKey),
        });
        patch.push(...taskRewardPatch(event.奖励 || event.结算记录, statData));
        return;
      }
      if (event.action === 'fail') {
        patch.push({
          op: 'replace',
          path: `/任务/${targetKey}`,
          value: taskRecord(mergeNonEmpty(current, {
            ...eventValue,
            名称: event.name || current['名称'],
            状态: '失败',
            当前进度: event.当前进度 || event.失败影响 || '任务失败',
          }), targetKey),
        });
        return;
      }
      patch.push({
        op: 'replace',
        path: `/任务/${targetKey}`,
        value: taskRecord(mergeNonEmpty(current, {
          ...eventValue,
          名称: event.name || current['名称'],
          状态: event.状态 || current['状态'] || '进行中',
          当前进度: event.当前进度 || current['当前进度'],
        }), targetKey),
      });
    });
    return patch;
  }

  function taskEventBlockFromRepair(rawTasks, statData) {
    const tasks = taskCollection(statData && statData['任务']);
    const blocks = [];
    (Array.isArray(rawTasks) ? rawTasks : []).forEach((raw) => {
      if (!raw || typeof raw !== 'object') return;
      const name = String(raw['名称'] || raw.name || '').trim();
      if (!name) return;
      const requestedKey = taskKeyFromName(raw['任务键'] || raw.key || name);
      if (!isMeaningfulTaskName(name, requestedKey)) return;
      const existingKey = findTaskKey(tasks, requestedKey, name, raw, false);
      const key = existingKey || requestedKey;
      const status = String(raw['状态'] || '').trim();
      const action = /失败/.test(status)
        ? '失败'
        : /已完成|完成/.test(status)
          ? '结算'
          : existingKey
            ? '推进'
            : '新建';
      if (action !== '新建' && action !== '结算') return;
      const fields = [
        ['任务键', key],
        ['动作', action],
        ['名称', name],
        ['类型', raw['类型']],
        ['状态', status],
        ['位阶', raw['位阶']],
        ['来源', raw['来源']],
        ['触发条件', raw['触发条件']],
        ['描述', raw['描述']],
        ['阶段', raw['阶段']],
        ['当前进度', raw['当前进度']],
        ['完成条件', raw['完成条件']],
        ['奖励', raw['奖励']],
        ['失败影响', raw['失败影响']],
        ['结算', raw['结算记录']],
      ].filter(([, value]) => value !== undefined && value !== null && String(value).trim() !== '');
      blocks.push([
        '<EdinaTaskEvent>',
        ...fields.map(([label, value]) => `${label}: ${String(value).trim()}`),
        '</EdinaTaskEvent>',
      ].join('\n'));
    });
    return blocks.join('\n\n');
  }

  function appendTaskEventBlock(message, block) {
    const source = String(message || '');
    const trimmed = String(block || '').trim();
    if (!trimmed || source.includes('<EdinaTaskEvent')) return source;
    const marker = source.search(/<UpdateVariable>|<StatusPlaceHolderImpl\b/i);
    if (marker >= 0) return `${source.slice(0, marker).trimEnd()}\n\n${trimmed}\n\n${source.slice(marker)}`;
    return `${source.trimEnd()}\n\n${trimmed}`;
  }

  function emitMessageUpdated(messageId) {
    try {
      const host = window.SillyTavern || (parent && parent.SillyTavern);
      const context = host && typeof host.getContext === 'function' ? host.getContext() : null;
      const eventTypes = context && context.eventTypes;
      const source = context && context.eventSource;
      const eventName = eventTypes && eventTypes.MESSAGE_UPDATED;
      if (source && eventName && typeof source.emit === 'function') source.emit(eventName, Number(messageId));
    } catch (_) {}
  }

  function notifyHudRefresh(messageId) {
    const payload = {
      type: 'edina:mvu-refresh',
      messageId: Number.isInteger(Number(messageId)) ? Number(messageId) : null,
    };
    const roots = [];
    try { roots.push(window.top || window); } catch (_) { roots.push(window); }
    try { if (parent && !roots.includes(parent)) roots.push(parent); } catch (_) {}
    const seen = new Set();
    const visit = (target, depth) => {
      if (!target || seen.has(target) || depth > 8) return;
      seen.add(target);
      let frames = null;
      try { frames = target.frames; } catch (_) {}
      if (!frames) return;
      for (let index = 0; index < frames.length; index += 1) {
        let child = null;
        try { child = frames[index]; } catch (_) {}
        if (!child) continue;
        try {
          if (typeof child.__ehxRefreshFromMvu === 'function') child.__ehxRefreshFromMvu();
        } catch (_) {}
        try { child.postMessage(payload, '*'); } catch (_) {}
        visit(child, depth + 1);
      }
    };
    roots.forEach((root) => visit(root, 0));
    roots.forEach((root) => {
      if (seen.has(root)) return;
      try {
        if (typeof root.__ehxRefreshFromMvu === 'function') root.__ehxRefreshFromMvu();
      } catch (_) {}
      try { root.postMessage(payload, '*'); } catch (_) {}
    });
  }

  async function installLegacyVariableBridge() {
    if (window.__edinaLegacyVariableBridgeInstalled) return;
    const events = window.tavern_events || (parent && parent.tavern_events);
    const eventName = events && events.MESSAGE_RECEIVED;
    if (!eventName) return;

    const makeFirst = await waitForGlobalFunction('eventMakeFirst', 8000);
    const on = makeFirst || await waitForGlobalFunction('eventOn', 8000);
    if (typeof on !== 'function') return;

    window.__edinaLegacyVariableBridgeInstalled = true;
    window.__edinaLegacyVariableBridgeMode = makeFirst ? 'before-mvu' : 'after-mvu';
    const activeStateRepairs = new Map();
    let stateWriteQueue = Promise.resolve();
    const publishRepairState = (messageId, phase, error = '') => {
      const detail = {
        pending: activeStateRepairs.size > 0,
        messageId: Number.isInteger(Number(messageId)) ? Number(messageId) : null,
        phase,
        error: String(error || ''),
        at: Date.now(),
      };
      try { window.__EDINA_STATE_REPAIR__ = detail; } catch (_) {}
      try { if (parent) parent.__EDINA_STATE_REPAIR__ = detail; } catch (_) {}
    };

    async function applyNormalizedUpdate(normalized, messageId) {
      const mvu = await waitForMvu(8000);
      if (!mvu || typeof mvu.parseMessage !== 'function' || typeof mvu.getMvuData !== 'function' || typeof mvu.replaceMvuData !== 'function') return;
      const option = { type: 'message', message_id: Number.isInteger(Number(messageId)) ? Number(messageId) : 'latest' };
      let before = null;
      try { before = mvu.getMvuData(option); } catch (_) {}
      if (!before || !before.stat_data) {
        option.message_id = 'latest';
        try { before = mvu.getMvuData(option); } catch (_) {}
      }
      if (!before || !before.stat_data) return;
      const snapshot = JSON.stringify(before.stat_data);
      await sleep(0);
      let current = null;
      try { current = mvu.getMvuData(option); } catch (_) {}
      if (!current || !current.stat_data) return;
      if (JSON.stringify(current.stat_data) !== snapshot) return;
      try {
        const parsed = await mvu.parseMessage(normalized, current);
        if (parsed && typeof parsed === 'object') await mvu.replaceMvuData(parsed, option);
      } catch (error) {
        console.warn('[艾迪娜 MVU] 规范化变量块解析失败，已跳过本楼补写', error);
      }
    }

    const handler = (messageId) => {
      const found = getChatMessageById(messageId);
      if (!found || !found.message || found.message.is_user) return;
      const before = String(found.message.mes || '');
      let statData = null;
      try {
        const mvu = getMvu();
        statData = getMvuStatData(mvu, messageId);
      } catch (_) {}
      const taskEvents = parseTaskEvents(before);
      const repair = repairNeeds(before, statData, found.chat, found.index);
      if (taskEvents.length) repair.needTasks = false;
      if (repair.needed || taskEvents.length) {
        const repairKey = String(found.index);
        if (!activeStateRepairs.has(repairKey)) {
          const task = stateWriteQueue
            .then(async () => {
              await sleep(300);
              const mvu = await waitForMvu(10000);
              const generate = await waitForGlobalFunction('generateRaw', 10000);
              if (!mvu || typeof mvu.parseMessage !== 'function' || typeof mvu.replaceMvuData !== 'function' || typeof generate !== 'function') return;
              const option = { type: 'message', message_id: found.index };
              const current = mvu.getMvuData(option);
              if (!current || !current.stat_data) return;
              if (taskEvents.length) {
                const eventPatch = taskEventPatch(taskEvents, current.stat_data);
                if (eventPatch.length) {
                  const parsedEvents = await mvu.parseMessage(buildVariableBlock('正文任务事件', eventPatch), current);
                  if (parsedEvents && typeof parsedEvents === 'object') {
                    await mvu.replaceMvuData(parsedEvents, option);
                    publish('task-event', 'state', `已处理第 ${found.index} 楼正文任务事件`);
                  }
                }
              }
              if (!repair.needed) return;
              const repairCurrent = mvu.getMvuData(option);
              if (!repairCurrent || !repairCurrent.stat_data) return;
              const narrative = narrativeText(before).slice(-6000);
              const userInput = latestUserMessageBefore(found.chat, found.index).slice(-1500);
              const snapshot = {
                用户输入: userInput,
                本轮正文: narrative,
                当前状态: {
                  基础: repairCurrent.stat_data['基础'] || {},
                  任务: repairCurrent.stat_data['任务'] || {},
                  关系: repairCurrent.stat_data['关系'] || {},
                },
                需要检查: {
                  任务: repair.needTasks,
                  关系: repair.needRelations,
                },
                待补关系: repair.missingWorldbookNames || [],
              };
              const prompt = [
                '你是角色卡状态修复器。只根据用户输入与正文中已经明确发生的事实，输出一个 JSON 对象，不要正文、解释、Markdown 或思考。',
                '格式：{"tasks":[完整任务对象],"relations":[人物对象]}。没有变化就返回 {"tasks":[],"relations":[]}。',
                '任务对象字段：任务键、名称、类型、状态、位阶、来源、触发条件、描述、完成条件、当前进度、奖励、失败影响、是否已结算、结算记录。只有明确的委托、危机、长期调查或既有任务推进才写；普通传闻和一次性闲聊不建任务。只有任务键完全一致或任务完整名称完全一致时才更新已有任务；禁止用相似名称、同一来源、同一类型做近似匹配。找不到完全一致的任务时必须写新任务键，绝不改动其他已有任务。',
                '人物对象字段：名字、身份、身份标签、位阶、好感、标签、在场、性别、一句话、外貌、身材、穿着、NSFW状态、等级、属性、装备、技能、头像。头像必须保持空字符串，绝不写图片 URL、data URL 或本机路径；默认头像和玩家自定义头像由前端本地处理。只记录有姓名、已与主角发生实际互动的剧情人物；仅被提及不算。新人物至少写名字和身份；已有角色只输出变化字段，但必须包含名字。明确离场时写在场=false，明确回归时写在场=true。好感只在关系实际变深或变差时给新的绝对值。禁止写“未命名角色”，也禁止把管理员、调查员、修士、村民、卫兵等职业或泛称当成人物姓名。',
              ].join('\n');
              const result = await generate({
                generation_id: `edina-state-repair-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
                should_stream: false,
                should_silence: true,
                ordered_prompts: [
                  { role: 'system', content: prompt },
                  { role: 'user', content: JSON.stringify(snapshot) },
                ],
                max_chat_history: 0,
              });
              const parsedRepair = parseStateRepair(typeof result === 'string' ? result : result?.content || '');
              if (!parsedRepair) {
                publish('repairing', 'state', `第 ${found.index} 楼状态修复未返回可解析 JSON`);
                return;
              }
              const repairPatch = stateRepairPatch(parsedRepair, repairCurrent.stat_data, repair);
              if (!repairPatch.length) return;
              const block = buildVariableBlock('静默状态修复', repairPatch);
              const parsed = await mvu.parseMessage(block, repairCurrent);
              if (parsed && typeof parsed === 'object') {
                await mvu.replaceMvuData(parsed, option);
                if (repair.needTasks && Array.isArray(parsedRepair.tasks)) {
                  const markerBlock = taskEventBlockFromRepair(parsedRepair.tasks, repairCurrent.stat_data);
                  const updatedMessage = appendTaskEventBlock(found.message.mes, markerBlock);
                  if (updatedMessage !== found.message.mes) {
                    found.message.mes = updatedMessage;
                    if (Array.isArray(found.message.swipes)) {
                      const swipeIndex = Number(found.message.swipe_id);
                      if (Number.isInteger(swipeIndex) && swipeIndex >= 0 && swipeIndex < found.message.swipes.length) {
                        found.message.swipes[swipeIndex] = updatedMessage;
                      }
                    }
                  }
                }
                // 静默补全只改 MVU 时不会产生普通消息更新，需主动通知前端重绘关系页。
                emitMessageUpdated(found.index);
                notifyHudRefresh(found.index);
                publish('repairing', 'state', `已补齐第 ${found.index} 楼任务/关系变化`);
              }
            })
            .catch((error) => {
              console.warn('[艾迪娜 MVU] 状态修复失败，已保留主回复原状', error);
            })
            .finally(() => {
              activeStateRepairs.delete(repairKey);
              publishRepairState(found.index, 'idle');
            });
          stateWriteQueue = task.catch(() => {});
          activeStateRepairs.set(repairKey, task);
          publishRepairState(found.index, 'pending');
        }
      }
      activeTaskCommand = parseTaskCommand(latestUserMessageBefore(found.chat, found.index));
      let after = before;
      try {
        after = normalizeLegacyVariablePayload(before, statData);
        after = stripNonCardTaskEvents(after);
      } finally {
        activeTaskCommand = null;
      }
      if (after === before) return;
      try { window.__edinaLastNormalizedMessage = after; } catch (_) {}
      const repairedRoster = after.includes('"/关系/名册/-"') || after.includes('\\"/关系/名册/-\\"');
      if (repairedRoster) publish('normalizing', 'bridge', `已为第 ${found.index} 楼补全关系名册 add 操作`);

      found.message.mes = after;
      if (Array.isArray(found.message.swipes)) {
        const swipeIndex = Number(found.message.swipe_id);
        if (Number.isInteger(swipeIndex) && swipeIndex >= 0 && swipeIndex < found.message.swipes.length) {
          found.message.swipes[swipeIndex] = after;
        }
      }
      publish('normalizing', 'bridge', `已将第 ${found.index} 楼的 JSON 变量块转换为 MVU 协议`);
      if (!makeFirst) void applyNormalizedUpdate(after, found.index);
    };
    makeFirst ? makeFirst(eventName, handler) : on(eventName, handler);
  }

  async function waitForGlobalFunction(name, timeoutMs) {
    const started = Date.now();
    while (Date.now() - started < timeoutMs) {
      if (typeof window[name] === 'function') return window[name];
      try { if (parent && typeof parent[name] === 'function') return parent[name]; } catch (_) {}
      await sleep(50);
    }
    return null;
  }

  async function waitForMvu(timeoutMs) {
    const immediate = getMvu();
    if (immediate) return immediate;

    if (typeof window.waitGlobalInitialized === 'function') {
      try {
        const pending = window.waitGlobalInitialized('Mvu');
        const timed = new Promise((resolve) => setTimeout(() => resolve(null), timeoutMs));
        const api = await Promise.race([pending, timed]);
        if (api || getMvu()) return api || getMvu();
      } catch (_) {}
    }

    const started = Date.now();
    while (Date.now() - started < timeoutMs) {
      const api = getMvu();
      if (api) return api;
      await sleep(50);
    }
    return getMvu();
  }

  function mapWorldbookEntry(entry) {
    return {
      uid: entry.id,
      name: entry.comment || `Entry ${entry.id}`,
      enabled: entry.enabled !== false,
      strategy: {
        type: entry.constant ? 'constant' : 'selective',
        keys: Array.isArray(entry.keys) ? entry.keys : [],
        keys_secondary: { logic: 'and_any', keys: [] },
        scan_depth: 'same_as_global',
      },
      position: {
        type: 'before_character_definition',
        role: 'system',
        depth: 0,
        order: Number.isFinite(entry.insertion_order) ? entry.insertion_order : 100,
      },
      content: String(entry.content || ''),
      probability: 100,
    };
  }

  // 世界书指纹：只跟 uid 与正文有关，用来判断宿主里已存在的同名世界书是不是这一版。
  function worldbookFingerprint(list) {
    const text = list.map((e) => `${e.uid != null ? e.uid : e.id}\u0001${String(e.content || '')}`).join('\u0002');
    let hash = 2166136261;
    for (let i = 0; i < text.length; i += 1) {
      hash ^= text.charCodeAt(i);
      hash = Math.imul(hash, 16777619);
    }
    return `${(hash >>> 0).toString(16)}-${list.length}`;
  }

  async function ensureWorldbook() {
    const namesFn = await waitForGlobalFunction('getWorldbookNames', 4000);
    if (!namesFn) throw new Error('世界书 API 未就绪');
    const names = namesFn() || [];
    const desired = EDINA_WORLDBOOK_ENTRIES.map(mapWorldbookEntry);
    const wantPrint = worldbookFingerprint(desired);
    const exists = names.includes(EDINA_WORLDBOOK_NAME);

    let needWrite = !exists;
    if (exists) {
      const getBook = await waitForGlobalFunction('getWorldbook', 4000);
      const current = getBook ? await getBook(EDINA_WORLDBOOK_NAME) : null;
      const currentPrint = Array.isArray(current) && current.length
        ? worldbookFingerprint(current.map((e) => ({ uid: e.uid != null ? e.uid : e.id, content: e.content })))
        : '';
      // 同名旧世界书必须整体替换：只判空会让重新导入的卡一直读到上一版内容。
      needWrite = currentPrint !== wantPrint;
      if (needWrite) publish('initializing', undefined, '检测到世界书与卡内不一致，准备整体替换');
    }

    if (needWrite) {
      // 优先「删除后重建」：这条路径与首次安装完全一致，实测比 replaceWorldbook 可靠。
      const deleteFn = await waitForGlobalFunction('deleteWorldbook', 3000);
      if (deleteFn) {
        await deleteFn(EDINA_WORLDBOOK_NAME);
        const createFn = await waitForGlobalFunction('createWorldbook', 4000);
        if (!createFn) throw new Error('createWorldbook 未就绪');
        await createFn(EDINA_WORLDBOOK_NAME, []);
        const addEntries = await waitForGlobalFunction('createWorldbookEntries', 4000);
        if (!addEntries) throw new Error('createWorldbookEntries 未就绪');
        await addEntries(EDINA_WORLDBOOK_NAME, desired);
      } else {
        const replaceFn = await waitForGlobalFunction('replaceWorldbook', 3000);
        if (!replaceFn) throw new Error('既没有 deleteWorldbook 也没有 replaceWorldbook');
        await replaceFn(EDINA_WORLDBOOK_NAME, desired);
      }
    }

    const getCharBooks = await waitForGlobalFunction('getCharWorldbookNames', 4000);
    const rebind = await waitForGlobalFunction('rebindCharWorldbooks', 4000);
    if (getCharBooks && rebind) {
      const bound = getCharBooks('current') || { primary: null, additional: [] };
      if (bound.primary !== EDINA_WORLDBOOK_NAME) {
        await rebind('current', { primary: EDINA_WORLDBOOK_NAME, additional: Array.isArray(bound.additional) ? bound.additional : [] });
      }
    }
    return EDINA_WORLDBOOK_NAME;
  }

  async function initializeMvuData(mvu) {
    if (!mvu || typeof mvu.getMvuData !== 'function' || typeof mvu.replaceMvuData !== 'function') return false;
    let data = null;
    try { data = mvu.getMvuData({ type: 'message', message_id: 'latest' }); } catch (_) {}
    if (!data || typeof data !== 'object') data = { initialized_lorebooks: {}, stat_data: {} };
    if (!data.initialized_lorebooks || typeof data.initialized_lorebooks !== 'object' || Array.isArray(data.initialized_lorebooks)) data.initialized_lorebooks = {};
    if (!data.stat_data || typeof data.stat_data !== 'object' || Array.isArray(data.stat_data)) data.stat_data = {};
    if (typeof mvu.reloadInitVar === 'function') await mvu.reloadInitVar(data);
    await mvu.replaceMvuData(data, { type: 'message', message_id: 'latest' });
    return true;
  }

  function applyDefaults(mvu) {
    if (!mvu || typeof mvu.setMvuDefaults !== 'function') return;
    try {
      mvu.setMvuDefaults({
        reprocessVariables: true,
        rereadInitialVariables: true,
        retryExtraModelParse: true,
        '重新处理变量': true,
        '重新读取初始变量': true,
        '重试额外模型解析': true,
      });
    } catch (error) {
      console.warn('[艾迪娜 MVU] 默认设置注入失败', error);
    }
  }

  async function importCode(code, source) {
    const url = URL.createObjectURL(new Blob([code], { type: 'text/javascript' }));
    try {
      await import(url);
    } catch (error) {
      const wrapped = new Error(`${source} 模块执行失败：${error && error.message ? error.message : error}`);
      wrapped.cause = error;
      throw wrapped;
    } finally {
      setTimeout(() => {
        try { URL.revokeObjectURL(url); } catch (_) {}
      }, 1000);
    }
  }

  async function loadRemote() {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 6000);
    try {
      const response = await fetch(EDINA_MVU_REMOTE, {
        method: 'GET',
        cache: 'no-store',
        credentials: 'omit',
        signal: controller.signal,
      });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const code = await response.text();
      if (!code || code.length < 1000) throw new Error('远程文件内容异常');
      await importCode(code, '远程 MVU');
    } finally {
      clearTimeout(timer);
    }
  }

  function decodeBase64(text) {
    const binary = atob(text);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
    return bytes;
  }

  async function inflateOffline(b64, label) {
    if (!b64 || b64.startsWith('__')) throw new Error(`${label}缺失。`);
    if (typeof DecompressionStream !== 'function') {
      throw new Error('当前浏览器不支持 DecompressionStream，无法解压卡内离线副本。');
    }
    const gz = decodeBase64(b64);
    const stream = new Blob([gz], { type: 'application/gzip' }).stream().pipeThrough(new DecompressionStream('gzip'));
    const code = await new Response(stream).text();
    if (!code || code.length < 1000) throw new Error(`${label}解压结果异常。`);
    return code;
  }

  async function loadLocal() {
    // 上游 MVU 产物把 Vue 当成外部全局，必须先注入卡内自带的 Vue 运行时。
    if (typeof window.Vue === 'undefined') {
      const vueCode = await inflateOffline(EDINA_VUE_LOCAL_B64, '卡内 Vue 运行时');
      // Vue 的 global 产物用顶层 var 声明。按 ES 模块导入时它只存在于模块作用域，
      // 不会自动挂到 window，因此这里补一段显式赋值，让依赖 window.Vue 的 MVU 产物能取到。
      await importCode(`${vueCode}\n;try{window.Vue=Vue;}catch(e){}\n`, '卡内 Vue 运行时');
      if (typeof window.Vue === 'undefined') throw new Error('卡内 Vue 运行时执行后仍未注册全局 Vue。');
    }
    const code = await inflateOffline(EDINA_MVU_LOCAL_B64, '卡内离线副本');
    await importCode(code, '卡内离线 MVU');
  }

  (async () => {
    void installLegacyVariableBridge();
    publish('starting', 'host', '先检查宿主是否已有 MVU');
    const existing = await waitForMvu(500);
    if (existing) {
      applyDefaults(existing);
      publish('initializing', 'host', '准备内置世界书与变量快照');
      await ensureWorldbook();
      await initializeMvuData(existing);
      publish('ready', 'host', '复用宿主 MVU，变量已初始化');
      return;
    }

    try {
      publish('loading', 'remote', '加载固定提交的远程 MVU');
      await loadRemote();
      const remote = await waitForMvu(8000);
      if (!remote) throw new Error('远程模块已执行，但 Mvu 未在超时内就绪');
      applyDefaults(remote);
      publish('initializing', 'remote', '准备内置世界书与变量快照');
      await ensureWorldbook();
      await initializeMvuData(remote);
      publish('ready', 'remote', '远程 MVU 已就绪，变量已初始化');
      return;
    } catch (remoteError) {
      try {
        publish('loading', 'local', `远程失败，切换卡内副本：${remoteError.message || remoteError}`);
        await loadLocal();
        const local = await waitForMvu(8000);
        if (!local) throw new Error('卡内模块已执行，但 Mvu 未在超时内就绪');
        applyDefaults(local);
        publish('initializing', 'local', '准备内置世界书与变量快照');
        await ensureWorldbook();
        await initializeMvuData(local);
        publish('ready', 'local', '卡内离线 MVU 已就绪，变量已初始化');
        return;
      } catch (localError) {
        publish('failed', 'none', `远程与卡内副本均失败。远程：${remoteError.message || remoteError}；本地：${localError.message || localError}`);
      }
    }
  })();
})();

